//! Build-time validation script for SSOT enforcement
//!
//! This script runs at compile time to ensure the SSOT architecture
//! is maintained. It validates that handlers are properly defined
//! and that no duplication exists.

use std::path::Path;

fn main() {
    println!("cargo:rerun-if-changed=src/");

    // Validate SSOT structure
    validate_ssot_structure();

    println!("cargo:warning=✅ SSOT validation passed");
}

fn validate_ssot_structure() {
    let src_dir = Path::new("src");

    // Check that all required SSOT files exist
    let required_files = [
        "models.rs",
        "handlers.rs",
        "transform.rs",
        "error.rs",
        "contracts.rs",
    ];

    for file in &required_files {
        let file_path = src_dir.join(file);
        if !file_path.exists() {
            panic!("SSOT validation failed: Missing required file {}", file);
        }
    }

    // Validate that handlers.rs contains the SSOT trait
    let handlers_content = std::fs::read_to_string(src_dir.join("handlers.rs"))
        .expect("Failed to read handlers.rs");

    if !handlers_content.contains("pub trait ApiHandler") {
        panic!("SSOT validation failed: ApiHandler trait not found in handlers.rs");
    }

    if !handlers_content.contains("analyze_repository") {
        panic!("SSOT validation failed: analyze_repository handler not found");
    }

    if !handlers_content.contains("analyze_dead_code") {
        panic!("SSOT validation failed: analyze_dead_code handler not found");
    }

    // Validate that models.rs contains TreeNode
    let models_content = std::fs::read_to_string(src_dir.join("models.rs"))
        .expect("Failed to read models.rs");

    if !models_content.contains("pub struct TreeNode") {
        panic!("SSOT validation failed: TreeNode not found in models.rs");
    }

    // Validate that contracts.rs contains tests
    let contracts_content = std::fs::read_to_string(src_dir.join("contracts.rs"))
        .expect("Failed to read contracts.rs");

    if !contracts_content.contains("#[test]") {
        panic!("SSOT validation failed: No contract tests found in contracts.rs");
    }

    if !contracts_content.contains("validate_tree_node_contract") {
        panic!("SSOT validation failed: Contract validation function not found");
    }

    println!("cargo:warning=✅ All SSOT structural requirements validated");
}

//! Contract Testing - SSOT Enforcement
//!
//! This module provides compile-time and test-time validation that both
//! Tauri and Web implementations produce identical API contracts.
//!
//! # SSOT Guarantees
//!
//! 1. **Type Safety**: Shared types enforce identical structure
//! 2. **Serialization Contracts**: Tests verify identical JSON output
//! 3. **Handler Contracts**: Trait enforces identical behavior
//! 4. **Snapshot Tests**: Catch any serialization changes

use crate::models::TreeNode;
use code_viz_dead_code::DeadCodeResult;
use serde::{Deserialize, Serialize};

/// Request/Response types that BOTH Tauri and Web must use
///
/// These types define the API contract. Any changes here affect both implementations.

#[derive(Debug, Clone, Serialize, Deserialize)]
#[serde(rename_all = "camelCase")]
pub struct AnalyzeRequest {
    pub path: String,
    #[serde(skip_serializing_if = "Option::is_none")]
    pub request_id: Option<String>,
}

#[derive(Debug, Clone, Serialize, Deserialize)]
#[serde(rename_all = "camelCase")]
pub struct AnalyzeResponse {
    pub tree: TreeNode,
}

#[derive(Debug, Clone, Serialize, Deserialize)]
#[serde(rename_all = "camelCase")]
pub struct DeadCodeRequest {
    pub path: String,
    pub min_confidence: u8,
    #[serde(skip_serializing_if = "Option::is_none")]
    pub request_id: Option<String>,
}

#[derive(Debug, Clone, Serialize, Deserialize)]
#[serde(rename_all = "camelCase")]
pub struct DeadCodeResponse {
    pub result: DeadCodeResult,
}

/// Contract validation - ensures both implementations produce identical JSON
#[cfg(test)]
pub mod test_utils {
    //! Test utilities for contract validation
    //!
    //! Note: unwrap() and expect() calls in tests are acceptable as test panics
    //! indicate fixture setup failures or assertion failures - which is expected
    //! behavior in test contexts.

    use super::*;
    use std::path::PathBuf;
    use std::time::SystemTime;

    pub use crate::transform::flat_to_hierarchy;

    // Re-export RealFileSystem for tests
    pub struct RealFileSystem;
    impl RealFileSystem {
        pub fn new() -> Self {
            Self
        }
    }

    impl code_viz_core::traits::FileSystem for RealFileSystem {
        fn read_dir_recursive(&self, path: &std::path::Path) -> anyhow::Result<Vec<PathBuf>> {
            let mut files = Vec::new();
            if path.is_dir() {
                for entry in std::fs::read_dir(path)? {
                    let entry = entry?;
                    let path = entry.path();
                    if path.is_file() {
                        files.push(path);
                    } else if path.is_dir() {
                        files.extend(self.read_dir_recursive(&path)?);
                    }
                }
            }
            Ok(files)
        }

        fn read_to_string(&self, path: &std::path::Path) -> anyhow::Result<String> {
            Ok(std::fs::read_to_string(path)?)
        }

        fn write(&self, path: &std::path::Path, content: &str) -> anyhow::Result<()> {
            Ok(std::fs::write(path, content)?)
        }

        fn exists(&self, path: &std::path::Path) -> bool {
            path.exists()
        }
    }

    /// Create a test TreeNode with known values for contract testing
    pub fn create_test_tree() -> TreeNode {
        TreeNode {
            id: "test.rs".to_string(),
            name: "test.rs".to_string(),
            path: PathBuf::from("test.rs"),
            loc: 100,
            complexity: 10,
            node_type: "file".to_string(),
            children: vec![],
            last_modified: SystemTime::UNIX_EPOCH + std::time::Duration::from_secs(1234567890),
            dead_code_ratio: None,
            language: Some("rust".to_string()),
            size_bytes: Some(2048),
            function_count: Some(5),
            coupling: None,
            code_churn: None,
            ai_bloat_index: None,
            cognitive_complexity: None,
            test_coverage: None,
        }
    }

    /// Validate that a TreeNode serializes to valid JSON with correct structure
    pub fn validate_tree_node_contract(tree: &TreeNode) -> Result<(), String> {
        let json = serde_json::to_value(tree)
            .map_err(|e| format!("Failed to serialize TreeNode: {}", e))?;

        // Validate required fields exist and have correct types
        if !json["id"].is_string() {
            return Err(format!("id must be string, got: {:?}", json["id"]));
        }
        if !json["name"].is_string() {
            return Err(format!("name must be string, got: {:?}", json["name"]));
        }
        if !json["path"].is_string() {
            return Err(format!("path must be string, got: {:?}", json["path"]));
        }
        if !json["loc"].is_number() {
            return Err(format!("loc must be number, got: {:?}", json["loc"]));
        }
        if !json["complexity"].is_number() {
            return Err(format!("complexity must be number, got: {:?}", json["complexity"]));
        }
        if !json["type"].is_string() {
            return Err(format!("type must be string, got: {:?}", json["type"]));
        }
        if !json["children"].is_array() {
            return Err(format!("children must be array, got: {:?}", json["children"]));
        }

        // CRITICAL: lastModified must be ISO 8601 string, NOT object
        if !json["lastModified"].is_string() {
            return Err(format!(
                "lastModified must be ISO 8601 string, got: {:?}",
                json["lastModified"]
            ));
        }

        let timestamp = json["lastModified"].as_str().unwrap();
        if !timestamp.contains('T') || !timestamp.ends_with('Z') {
            return Err(format!(
                "lastModified must be ISO 8601 with Z suffix, got: {}",
                timestamp
            ));
        }

        Ok(())
    }
}

#[cfg(test)]
mod tests {
    //! Contract validation tests
    //!
    //! Note: unwrap() and expect() calls in tests are acceptable as test panics
    //! indicate fixture setup failures or assertion failures - which is expected
    //! behavior in test contexts.

    use super::*;
    use test_utils::*;

    #[test]
    fn test_analyze_request_serialization() {
        let request = AnalyzeRequest {
            path: "/test/path".to_string(),
            request_id: Some("test-123".to_string()),
        };

        let json = serde_json::to_string(&request).unwrap();
        insta::assert_snapshot!(json, @r###"{"path":"/test/path","requestId":"test-123"}"###);
    }

    #[test]
    fn test_analyze_response_contract() {
        let tree = create_test_tree();
        let response = AnalyzeResponse { tree: tree.clone() };

        // Validate contract
        validate_tree_node_contract(&response.tree).unwrap();

        // Snapshot test - catches any serialization changes
        let json = serde_json::to_value(&response).unwrap();
        insta::assert_json_snapshot!(json);
    }

    #[test]
    fn test_dead_code_request_serialization() {
        let request = DeadCodeRequest {
            path: "/test/path".to_string(),
            min_confidence: 80,
            request_id: Some("test-456".to_string()),
        };

        let json = serde_json::to_string(&request).unwrap();
        insta::assert_snapshot!(json, @r###"{"path":"/test/path","minConfidence":80,"requestId":"test-456"}"###);
    }

    /// CRITICAL: This test enforces SSOT - if JSON structure changes,
    /// both Tauri and Web must update together
    #[test]
    fn test_tree_node_json_contract() {
        let tree = create_test_tree();

        let json_str = serde_json::to_string_pretty(&tree).unwrap();

        // This snapshot MUST match for both Tauri and Web
        insta::assert_snapshot!(json_str);

        // Validate no raw SystemTime objects leak through
        assert!(
            !json_str.contains("secs_since_epoch"),
            "JSON must not contain raw SystemTime fields"
        );
        assert!(
            json_str.contains("lastModified"),
            "JSON must contain lastModified field"
        );
    }

    #[test]
    fn test_tree_node_roundtrip() {
        let original = create_test_tree();

        // Serialize
        let json_str = serde_json::to_string(&original).unwrap();

        // Deserialize
        let deserialized: TreeNode = serde_json::from_str(&json_str).unwrap();

        // Values should match
        assert_eq!(original.id, deserialized.id);
        assert_eq!(original.name, deserialized.name);
        assert_eq!(original.loc, deserialized.loc);
        assert_eq!(original.complexity, deserialized.complexity);
    }
}

//! Shared error types for API handlers
//!
//! This module defines the error types used across both Tauri and Web implementations.

use thiserror::Error;

#[derive(Debug, Error)]
pub enum ApiError {
    #[error("Analysis failed: {0}")]
    AnalysisFailed(String),

    #[error("Dead code analysis failed: {0}")]
    DeadCodeFailed(String),

    #[error("Invalid path: {0}")]
    InvalidPath(String),

    #[error("Transform error: {0}")]
    TransformError(String),

    #[error("IO error: {0}")]
    Io(#[from] std::io::Error),

    #[error("Internal error: {0}")]
    Internal(#[from] anyhow::Error),
}

impl ApiError {
    /// Convert to a user-friendly error message string
    pub fn to_user_message(&self) -> String {
        match self {
            ApiError::AnalysisFailed(msg) => format!("Analysis failed: {}", msg),
            ApiError::DeadCodeFailed(msg) => format!("Dead code analysis failed: {}", msg),
            ApiError::InvalidPath(msg) => format!("Invalid path: {}", msg),
            ApiError::TransformError(msg) => format!("Transform error: {}", msg),
            ApiError::Io(e) => format!("File system error: {}", e),
            ApiError::Internal(e) => format!("Internal error: {}", e),
        }
    }
}

//! Shared API handlers - Single Source of Truth
//!
//! This module defines the handler trait and implementations that BOTH
//! Tauri and Web must use. This ensures compile-time consistency.

use crate::error::ApiError;
use crate::models::{TreeNode, AnalysisOptions};
use crate::transform::flat_to_hierarchy;
use code_viz_commands::analyze::{DuplicationConfig, HotspotConfig, CoverageConfig};
use code_viz_core::traits::{AppContext, FileSystem, GitProvider};
use code_viz_dead_code::DeadCodeResult;
use std::path::PathBuf;

/// SSOT Handler Trait - Both Tauri and Web MUST implement this
///
/// This trait defines the complete API surface. Any handler that implements
/// this trait is guaranteed to have the same interface, preventing drift.
#[async_trait::async_trait]
pub trait ApiHandler: Send + Sync {
    /// Analyze a repository and return hierarchical tree structure
    async fn analyze_repository(
        &self,
        path: String,
        options: AnalysisOptions,
        request_id: Option<String>,
    ) -> Result<TreeNode, ApiError>;

    /// Analyze dead code in a repository
    async fn analyze_dead_code(
        &self,
        path: String,
        min_confidence: u8,
        request_id: Option<String>,
    ) -> Result<DeadCodeResult, ApiError>;
}

/// Shared handler implementation using dependency injection
///
/// This is the actual business logic that both Tauri and Web use.
/// They just provide different Context implementations.
///
/// Note: This struct stores references to avoid cloning. For use with
/// impl Trait functions, use the standalone handler functions instead.
pub struct SharedHandler<C, F, G>
where
    C: AppContext + Clone,
    F: FileSystem + Clone,
    G: GitProvider + Clone,
{
    ctx: C,
    fs: F,
    git: G,
}

impl<C, F, G> SharedHandler<C, F, G>
where
    C: AppContext + Clone,
    F: FileSystem + Clone,
    G: GitProvider + Clone,
{
    pub fn new(ctx: C, fs: F, git: G) -> Self {
        Self { ctx, fs, git }
    }
}

#[async_trait::async_trait]
impl<C, F, G> ApiHandler for SharedHandler<C, F, G>
where
    C: AppContext + Clone + Send + Sync,
    F: FileSystem + Clone + Send + Sync,
    G: GitProvider + Clone + Send + Sync,
{
    async fn analyze_repository(
        &self,
        path: String,
        options: AnalysisOptions,
        _request_id: Option<String>,
    ) -> Result<TreeNode, ApiError> {
        let repo_path = PathBuf::from(&path);

        // Convert options to config types (transparent pass-through, no business logic)
        let duplication_config = if options.enable_duplicates {
            Some(DuplicationConfig {
                min_lines: options.min_duplicate_lines.unwrap_or(5),
                similarity_threshold: 0.8,
            })
        } else {
            None
        };

        let hotspot_config = if options.enable_hotspots {
            Some(HotspotConfig {
                max_hotspots: options.max_hotspots.unwrap_or(10),
            })
        } else {
            None
        };

        let coverage_config = options.coverage_report_path.map(|path| {
            CoverageConfig {
                report_path: PathBuf::from(path),
            }
        });

        // Call framework-agnostic command layer (clones because impl Trait consumes)
        let analysis_result = code_viz_commands::analyze_repository(
            &repo_path,
            self.ctx.clone(),
            self.fs.clone(),
            &self.git.clone(),
            duplication_config,
            hotspot_config,
            coverage_config,
        )
        .await
        .map_err(|e| ApiError::AnalysisFailed(e.to_string()))?;

        // Transform flat metrics to hierarchical tree (presentation layer)
        let tree = flat_to_hierarchy(analysis_result.files)?;

        Ok(tree)
    }

    async fn analyze_dead_code(
        &self,
        path: String,
        min_confidence: u8,
        _request_id: Option<String>,
    ) -> Result<DeadCodeResult, ApiError> {
        let repo_path = PathBuf::from(&path);

        // Call framework-agnostic command layer (clones because impl Trait consumes)
        let analysis_result = code_viz_commands::calculate_dead_code(
            &repo_path,
            self.ctx.clone(),
            self.fs.clone(),
            self.git.clone(),
        )
        .await
        .map_err(|e| ApiError::DeadCodeFailed(e.to_string()))?;

        // Filter by confidence score (presentation layer)
        let filtered_result = analysis_result.filter_by_confidence(min_confidence);

        Ok(filtered_result)
    }
}

/// Standalone handler functions for frameworks that don't use traits
///
/// These are convenience wrappers for simple function-based APIs.
/// Useful for Tauri which prefers free functions.
pub async fn analyze_repository_handler<C, F, G>(
    ctx: C,
    fs: F,
    git: G,
    path: String,
    options: AnalysisOptions,
    _request_id: Option<String>,
) -> Result<TreeNode, ApiError>
where
    C: AppContext,
    F: FileSystem,
    G: GitProvider,
{
    let repo_path = PathBuf::from(&path);

    // Convert options to config types (transparent pass-through, no business logic)
    let duplication_config = if options.enable_duplicates {
        Some(DuplicationConfig {
            min_lines: options.min_duplicate_lines.unwrap_or(5),
            similarity_threshold: 0.8,
        })
    } else {
        None
    };

    let hotspot_config = if options.enable_hotspots {
        Some(HotspotConfig {
            max_hotspots: options.max_hotspots.unwrap_or(10),
        })
    } else {
        None
    };

    let coverage_config = options.coverage_report_path.map(|path| {
        CoverageConfig {
            report_path: PathBuf::from(path),
        }
    });

    let analysis_result = code_viz_commands::analyze_repository(
        &repo_path,
        ctx,
        fs,
        &git,
        duplication_config,
        hotspot_config,
        coverage_config,
    )
    .await
    .map_err(|e| ApiError::AnalysisFailed(e.to_string()))?;

    let tree = flat_to_hierarchy(analysis_result.files)?;

    Ok(tree)
}

pub async fn analyze_dead_code_handler<C, F, G>(
    ctx: C,
    fs: F,
    git: G,
    path: String,
    min_confidence: u8,
    _request_id: Option<String>,
) -> Result<DeadCodeResult, ApiError>
where
    C: AppContext,
    F: FileSystem,
    G: GitProvider,
{
    let repo_path = PathBuf::from(&path);

    let analysis_result = code_viz_commands::calculate_dead_code(&repo_path, ctx, fs, git)
        .await
        .map_err(|e| ApiError::DeadCodeFailed(e.to_string()))?;

    let filtered_result = analysis_result.filter_by_confidence(min_confidence);

    Ok(filtered_result)
}

#[cfg(test)]
mod tests {
    use super::*;
    use code_viz_core::mocks::{MockContext, MockGit};
    use crate::contracts::test_utils::RealFileSystem;

    #[tokio::test]
    async fn test_handler_analyze_repository() {
        let ctx = MockContext::new();
        let fs = RealFileSystem::new();
        let current_dir = std::env::current_dir()
            .unwrap()
            .to_string_lossy()
            .to_string();

        let git = code_viz_core::context::RealGit::new();
        let options = AnalysisOptions::default();
        let result = analyze_repository_handler(ctx, fs, git, current_dir, options, None).await;
        assert!(result.is_ok(), "Handler should succeed: {:?}", result);
    }

    #[tokio::test]
    async fn test_handler_analyze_dead_code() {
        let ctx = MockContext::new();
        let fs = RealFileSystem::new();
        let git = MockGit::new();
        let current_dir = std::env::current_dir()
            .unwrap()
            .to_string_lossy()
            .to_string();

        let result = analyze_dead_code_handler(ctx, fs, git, current_dir, 70, None).await;
        // Dead code analysis may fail if no entry points found, which is acceptable
        match result {
            Ok(_) => {}, // Success case
            Err(ApiError::DeadCodeFailed(msg)) if msg.contains("No entry points") => {}, // Expected
            Err(e) => panic!("Unexpected error: {:?}", e),
        }
    }
}

//! Shared API layer for code-viz
//!
//! This crate provides the Single Source of Truth (SSOT) for all API handlers,
//! models, and transformations. Both Tauri and Web implementations depend on
//! this crate to ensure zero duplication and compile-time consistency.
//!
//! # Architecture
//!
//! ```text
//! ┌─────────────────────────────────────────┐
//! │  code-viz-api (THIS CRATE)              │
//! │  - Shared types (TreeNode, etc.)        │
//! │  - Handler trait (SSOT contract)        │
//! │  - Transformations (flat_to_hierarchy)  │
//! │  - Contract tests (JSON validation)     │
//! └─────────────────────────────────────────┘
//!          ▲                         ▲
//!          │                         │
//!   ┌──────┴────────┐       ┌───────┴────────┐
//!   │ code-viz-tauri│       │ code-viz-web   │
//!   │ (IPC wrapper) │       │ (HTTP wrapper) │
//!   └───────────────┘       └────────────────┘
//! ```

pub mod models;
pub mod transform;
pub mod handlers;
pub mod error;
pub mod contracts;

pub use models::*;
pub use handlers::*;
pub use error::*;

//! Data models for visualization
//!
//! This module defines the TreeNode structure used for hierarchical
//! visualization of code metrics in the frontend, and AnalysisOptions
//! for configuring which analysis features to enable.

use serde::{Deserialize, Serialize, Serializer, Deserializer};
use std::path::PathBuf;
use std::time::SystemTime;

/// Analysis options - configure which features to enable
///
/// This struct is a transparent pass-through to CLI options.
/// No logic here - just transport from frontend to backend.
#[derive(Debug, Clone, Serialize, Deserialize, Default)]
#[serde(rename_all = "camelCase")]
pub struct AnalysisOptions {
    /// Enable code duplication detection
    #[serde(default)]
    pub enable_duplicates: bool,

    /// Minimum lines for duplicate detection (default: 5)
    #[serde(skip_serializing_if = "Option::is_none")]
    pub min_duplicate_lines: Option<usize>,

    /// Enable git hotspot detection
    #[serde(default)]
    pub enable_hotspots: bool,

    /// Maximum number of hotspots to report (default: 10)
    #[serde(skip_serializing_if = "Option::is_none")]
    pub max_hotspots: Option<usize>,

    /// Enable AI commit analysis
    #[serde(default)]
    pub enable_ai_commits: bool,

    /// Path to test coverage report (llvm-cov or Tarpaulin JSON)
    #[serde(skip_serializing_if = "Option::is_none")]
    pub coverage_report_path: Option<String>,
}

/// Serialize SystemTime as ISO 8601 string with Z suffix for UTC
pub fn serialize_systemtime<S>(time: &SystemTime, serializer: S) -> Result<S::Ok, S::Error>
where
    S: Serializer,
{
    let datetime: chrono::DateTime<chrono::Utc> = (*time).into();
    // Use true parameter to force Z suffix instead of +00:00
    serializer.serialize_str(&datetime.to_rfc3339_opts(chrono::SecondsFormat::Millis, true))
}

/// Deserialize SystemTime from ISO 8601 string
pub fn deserialize_systemtime<'de, D>(deserializer: D) -> Result<SystemTime, D::Error>
where
    D: Deserializer<'de>,
{
    let s = String::deserialize(deserializer)?;
    let datetime = chrono::DateTime::parse_from_rfc3339(&s)
        .map_err(serde::de::Error::custom)?
        .with_timezone(&chrono::Utc);
    Ok(datetime.into())
}

/// Hierarchical node representing a file or directory in the codebase tree
///
/// This structure extends the core FileMetrics with hierarchical relationships
/// and visualization-specific fields for rendering in the treemap UI.
#[derive(Debug, Clone, Serialize, Deserialize)]
#[serde(rename_all = "camelCase")]
pub struct TreeNode {
    /// Unique identifier for this node (typically the full path)
    pub id: String,

    /// Display name (file/directory name without full path)
    pub name: String,

    /// Full path from repository root
    pub path: PathBuf,

    /// Lines of code (for files) or sum of children (for directories)
    pub loc: usize,

    /// Complexity score (0-100 scale, calculated as loc/10 for MVP)
    /// This is a placeholder metric; future versions may use cyclomatic complexity
    pub complexity: u32,

    /// Node type: "file" or "directory"
    #[serde(rename = "type")]
    pub node_type: String,

    /// Child nodes (empty for files, contains children for directories)
    #[serde(default)]
    pub children: Vec<TreeNode>,

    /// Last modified timestamp (for cache invalidation and sorting)
    #[serde(serialize_with = "serialize_systemtime", deserialize_with = "deserialize_systemtime")]
    pub last_modified: SystemTime,

    /// Dead code ratio (0.0 to 1.0), only present when dead code analysis is enabled
    #[serde(skip_serializing_if = "Option::is_none")]
    pub dead_code_ratio: Option<f64>,

    // Additional metrics from FileMetrics (only present for files, not directories)

    /// Programming language ("rust", "typescript", "python", etc.) - only for files
    #[serde(skip_serializing_if = "Option::is_none")]
    pub language: Option<String>,

    /// File size in bytes - only for files
    #[serde(skip_serializing_if = "Option::is_none")]
    pub size_bytes: Option<u64>,

    /// Number of functions/methods - only for files
    #[serde(skip_serializing_if = "Option::is_none")]
    pub function_count: Option<usize>,

    /// Coupling metrics (afferent, efferent, instability)
    #[serde(skip_serializing_if = "Option::is_none")]
    pub coupling: Option<code_viz_core::models::CouplingMetrics>,

    /// Code churn metrics (lines added/deleted from git)
