#[derive(Error, Debug)]
pub enum WatchError {
    #[error("Watch setup failed: {0}")]
    NotifyError(#[from] notify::Error),

    #[error("Analysis failed: {0}")]
    AnalysisError(#[from] anyhow::Error),

    #[error("Config error: {0}")]
    ConfigError(#[from] crate::config_loader::ConfigError),

    #[error("I/O error: {0}")]
    IoError(#[from] std::io::Error),

    #[error("Formatting failed: {0}")]
    FormattingFailed(#[from] crate::output::FormatterError),
}

pub async fn run(path: PathBuf, format: String, verbose: bool, ctx: impl AppContext + Clone, fs: impl FileSystem + Clone) -> Result<(), WatchError> {
    // Setup logging
    let mut builder = env_logger::Builder::from_default_env();
    if verbose {
        builder.filter_level(log::LevelFilter::Debug);
    } else {
        builder.filter_level(log::LevelFilter::Info);
    }
    let _ = builder.try_init();

    // Load config
    let mut config = AnalysisConfig::default();
    let current_dir = std::env::current_dir()?;
    let file_config = config_loader::load_config(&current_dir)?;
    if let Some(analysis) = file_config.analysis {
        if let Some(file_excludes) = analysis.exclude {
            config.exclude_patterns = file_excludes;
        }
    }

    // Initial analysis
    if format != "json" {
        println!("Performing initial analysis...");
    }
    let git = code_viz_core::context::RealGit::new();
    let mut current_result = analyze_repository(&path, ctx.clone(), fs.clone(), &git, None, None, None).await?;
    print_output(&current_result, &format)?;

    // Setup channel
    let (tx, rx) = channel();

    // Setup watcher
    let mut watcher = RecommendedWatcher::new(tx, Config::default())?;
    watcher.watch(&path, RecursiveMode::Recursive)?;

    if format != "json" {
        println!("Watching for changes in {}...", path.display());
    }

    // Setup Ctrl+C handler
    let running = Arc::new(Mutex::new(true));
    let r = running.clone();
    ctrlc::set_handler(move || {
        // Safety: Mutex lock should never fail here as we control all access points
        // and don't panic while holding the lock
        if let Ok(mut running) = r.lock() {
            *running = false;
        }
        // We can't break the loop easily from here unless we send a signal or checking flag
        // The main loop checks flag
    }).map_err(|e| WatchError::IoError(std::io::Error::other(format!("Failed to set Ctrl-C handler: {}", e))))?;

    // Loop
    loop {
        // Check running flag
        // Safety: Mutex lock should never fail as we control all access and don't panic while holding lock
        let should_stop = running.lock()
            .map(|guard| !*guard)
            .unwrap_or(true); // If mutex is poisoned, stop watching

        if should_stop {
            if format != "json" {
                println!("\nStopping watch mode...");
            }
            break;
        }

        // Wait for event (with timeout to check running flag periodically if needed, 
        // but recv() blocks. Ctrl+C handler can exit process or we use timeout loop)
        // Ideally we use a select or timeout.
        // Let's use recv_timeout loop to check running flag.
        let event_res = rx.recv_timeout(Duration::from_millis(500));

        match event_res {
            Ok(event_res) => {
                match event_res {
                    Ok(event) => {
                        // Collect events for debounce window (100ms)
                        let mut changed_paths = HashSet::new();
                        add_paths_from_event(&mut changed_paths, event);

                        let deadline = SystemTime::now() + Duration::from_millis(100);
                        while let Ok(dur) = deadline.duration_since(SystemTime::now()) {
                            if let Ok(res) = rx.recv_timeout(dur) {
                                if let Ok(e) = res {
                                    add_paths_from_event(&mut changed_paths, e);
                                }
                            } else {
                                break; // Timeout (debounce window end) or Disconnected
                            }
                        }

                        if !changed_paths.is_empty() {
                            handle_changes(&mut current_result, changed_paths, &format, &fs)?;
                        }
                    }
                    Err(e) => eprintln!("Watch error: {}", e),
                }
            }
            Err(RecvTimeoutError::Timeout) => continue, // Just loop to check running flag
            Err(RecvTimeoutError::Disconnected) => break,
        }
    }

    Ok(())
}

fn add_paths_from_event(paths: &mut HashSet<PathBuf>, event: notify::Event) {
    for path in event.paths {
        // Filter by extension
        if let Some(ext) = path.extension() {
            match ext.to_string_lossy().as_ref() {
                "ts" | "tsx" | "js" | "jsx" | "rs" | "py" => {
                    paths.insert(path);
                }
                _ => {}
            }
        }
    }
}

fn handle_changes(
    result: &mut AnalysisResult,
    paths: HashSet<PathBuf>,
    format: &str,
    fs: &impl FileSystem,
) -> Result<(), WatchError> {
    let mut updated = false;

    for path in paths {
        // Check if file exists (modification/creation) or deleted
        if path.exists() {
            // Re-analyze file
            match process_file_with_fs(&path, fs) {
                Ok(metrics) => {
                    let metrics_path = metrics.path.clone();
                    let metrics_loc = metrics.loc;
                    let metrics_function_count = metrics.function_count;

                    // Update result.files
                    if let Some(existing) = result.files.iter_mut().find(|f| f.path == metrics.path) {
                        *existing = metrics;
                    } else {
                        result.files.push(metrics);
                    }

                    if format != "json" {
                        // Print update using captured values
                        println!(
                            "[{}] {}: {} LOC ({} funcs)",
                            chrono::Local::now().format("%H:%M:%S"),
                            metrics_path.display(),
                            metrics_loc,
                            metrics_function_count
                        );
                    }
                    updated = true;
                }
                Err(e) => {
                    eprintln!("Failed to re-analyze {:?}: {}", path, e);
                }
            }
        } else {
            // File deleted
            if let Some(idx) = result.files.iter().position(|f| f.path == path) {
                result.files.remove(idx);
                if format != "json" {
                    println!("[{}] Deleted: {}", chrono::Local::now().format("%H:%M:%S"), path.display());
                }
                updated = true;
            }
        }
    }

    if updated {
        // Re-calculate summary
        result.summary = calculate_summary(&result.files);
        result.timestamp = SystemTime::now();

        if format == "json" {
            print_output(result, format)?;
        }
    }

    Ok(())
}

fn print_output(result: &AnalysisResult, format: &str) -> Result<(), WatchError> {
    if format == "json" {
        // Compact JSON on one line
        let json = serde_json::to_string(result).map_err(|_| crate::output::FormatterError::FormattingFailed)?;
        println!("{}", json);
    } else {
        // For text, we printed incremental updates.
        // Maybe print summary again?
        // "print updated metrics ... if --format json ... else print '[timestamp] path: X LOC'"
        // So for text mode, we don't print full summary every time, just the update line.
        // Initial analysis prints full summary.
        if !result.files.is_empty() { // Check if initial call
             // Actually `run` calls `print_output` for initial result.
             // If format is text, we want full summary.
             // But inside loop, we handle incremental prints manually.
             // So `print_output` is mainly for JSON or initial Text.

             // How to distinguish?
             // `run` calls `print_output` initially.
             // `handle_changes` calls `print_output` ONLY if JSON.
             // Text updates are handled in `handle_changes` loop.
             // So we are good.

             if format != "json" {
                 // Use TextFormatter
                 let formatter = output::text::TextFormatter;
                 let output = formatter.format(result)?;
                 println!("{}", output);
             }
        }
    }
    Ok(())
}

use serde::Deserialize;
use std::fs;
use std::path::Path;
use thiserror::Error;

#[derive(Error, Debug)]
pub enum ConfigError {
    #[error("Config parse failed: {0}")]
    ParseFailed(#[from] toml::de::Error),

    #[error("I/O error: {0}")]
    IoError(#[from] std::io::Error),
}

#[derive(Debug, Deserialize, Default)]
pub struct ConfigFile {
    pub analysis: Option<AnalysisConfigSection>,
    #[allow(dead_code)]
    pub output: Option<OutputConfigSection>,
    #[allow(dead_code)]
    pub cache: Option<CacheConfigSection>,
}

#[derive(Debug, Deserialize)]
pub struct AnalysisConfigSection {
    pub exclude: Option<Vec<String>>,
}

#[derive(Debug, Deserialize)]
pub struct OutputConfigSection {
    #[allow(dead_code)]
    pub format: Option<String>,
}

#[derive(Debug, Deserialize)]
pub struct CacheConfigSection {
    #[allow(dead_code)]
    pub enabled: Option<bool>,
}

pub fn load_config(project_root: &Path) -> Result<ConfigFile, ConfigError> {
    let config_path = project_root.join(".code-viz.toml");

    if !config_path.exists() {
        return Ok(ConfigFile::default());
    }

    let content = fs::read_to_string(&config_path)?;
    let config: ConfigFile = toml::from_str(&content)?;

    Ok(config)
}

#[cfg(test)]
mod tests {
    //! Test module for configuration loading.
    //!
    //! Note: unwrap() calls in tests are acceptable as test panics indicate
    //! test fixture setup failures or assertion failures, which is the expected
    //! behavior in test contexts.

    use super::*;
    use tempfile::TempDir;
    use std::io::Write;
    use std::fs::File;

    #[test]
    fn test_load_valid_config() {
        let temp_dir = TempDir::new().unwrap();
        let root = temp_dir.path();

        let mut f = File::create(root.join(".code-viz.toml")).unwrap();
        writeln!(f, r#"
            [analysis]
            exclude = ["node_modules/**", "dist/**"]

            [output]
            format = "json"

            [cache]
            enabled = true
        "#).unwrap();

        let config = load_config(root).unwrap();

        assert!(config.analysis.is_some());
        let analysis = config.analysis.unwrap();
        assert_eq!(analysis.exclude.unwrap().len(), 2);

        assert!(config.output.is_some());
        assert_eq!(config.output.unwrap().format.unwrap(), "json");

        assert!(config.cache.is_some());
        assert_eq!(config.cache.unwrap().enabled.unwrap(), true);
    }

    #[test]
    fn test_load_missing_config() {
        let temp_dir = TempDir::new().unwrap();
        let config = load_config(temp_dir.path()).unwrap();
        assert!(config.analysis.is_none());
    }

    #[test]
    fn test_load_invalid_toml() {
        let temp_dir = TempDir::new().unwrap();
        let root = temp_dir.path();

        let mut f = File::create(root.join(".code-viz.toml")).unwrap();
        writeln!(f, "invalid toml [").unwrap();

        let result = load_config(root);
        assert!(result.is_err());
        assert!(matches!(result.err().unwrap(), ConfigError::ParseFailed(_)));
    }
}

use anyhow::Result;
use async_trait::async_trait;
use code_viz_core::traits::AppContext;
use serde_json::Value;
use std::path::PathBuf;

/// CLI implementation of AppContext that prints to stdout/stderr.
#[derive(Clone)]
pub struct CliContext {
    verbose: bool,
}

impl CliContext {
    /// Create a new CliContext with the given verbosity.
    pub fn new(verbose: bool) -> Self {
        Self { verbose }
    }
}

#[async_trait]
impl AppContext for CliContext {
    async fn emit_event(&self, event: &str, payload: Value) -> Result<()> {
        if self.verbose {
            println!("[{}] {}", event, payload);
        }
        Ok(())
    }

    fn get_app_dir(&self) -> PathBuf {
        std::env::current_dir().unwrap_or_else(|_| PathBuf::from("."))
    }

    async fn report_progress(&self, percentage: f32, message: &str) -> Result<()> {
        // Report progress to stderr to keep stdout clean for JSON output or other data.
        eprintln!("{:.0}% - {}", percentage * 100.0, message);
        Ok(())
    }
}

use clap::{Parser, Subcommand};
use std::path::PathBuf;
use crate::context::CliContext;
use crate::commands::compare::CompareCommand;
use code_viz_core::context::{RealFileSystem, RealGit};

mod commands;
mod config_loader;
mod context;
mod output;

#[derive(Parser)]
#[command(author, version, about, long_about = None)]
struct Cli {
    #[command(subcommand)]
    command: Commands,
}

#[derive(Subcommand)]
enum Commands {
    /// Analyze a directory and generate metrics
    Analyze {
        /// Path to the directory to analyze
        #[arg(default_value = ".")]
        path: PathBuf,

        /// Output format (json, csv, text)
        #[arg(long, short, default_value = "text")]
        format: String,

        /// Glob patterns to exclude
        #[arg(long, short)]
        exclude: Vec<String>,

        /// Enable verbose logging
        #[arg(long, short)]
        verbose: bool,

        /// Fail if metrics exceed threshold (e.g., "loc=500")
        #[arg(long)]
        threshold: Option<String>,

        /// Write output to file instead of stdout
        #[arg(long, short)]
        output: Option<PathBuf>,

        /// Compare against a baseline report
        #[arg(long)]
        baseline: Option<PathBuf>,

        /// Enable dead code analysis
        #[arg(long)]
        dead_code: bool,

        /// Enable code duplication analysis
        #[arg(long)]
        duplicates: bool,

        /// Minimum number of lines for a code block to be considered a duplicate
        #[arg(long, default_value = "5")]
        min_duplicate_lines: usize,

        /// Enable AI commit analysis
        #[arg(long)]
        ai_commits: bool,

        /// Enable git hotspot analysis
        #[arg(long)]
        hotspots: bool,

        /// Maximum number of hotspots to report
        #[arg(long, default_value = "10")]
        max_hotspots: usize,

        /// Path to test coverage report (llvm-cov or Tarpaulin JSON)
        #[arg(long)]
        coverage_report: Option<PathBuf>,
    },
    /// Watch a directory for changes and re-analyze
    Watch {
        /// Path to the directory to watch
        #[arg(default_value = ".")]
        path: PathBuf,

        /// Output format (json, text)
        #[arg(long, short, default_value = "text")]
        format: String,

        /// Enable verbose logging
        #[arg(long, short)]
        verbose: bool,
    },
    /// Compare two analysis reports
    Diff {
        /// Path to the old report
        old: PathBuf,

        /// Path to the new report
        new: PathBuf,
    },
    /// Configuration management
    Config {
        #[command(subcommand)]
        subcommand: ConfigSubcommand,
    },
    /// Analyze dead code in a directory
    DeadCode {
        /// Path to the directory to analyze
        #[arg(default_value = ".")]
        path: PathBuf,

        /// Output format (json, text)
        #[arg(long, short, default_value = "text")]
        format: String,

        /// Minimum confidence score (0-100)
        #[arg(long, default_value = "80")]
        min_confidence: u8,

        /// Glob patterns to exclude
        #[arg(long, short)]
        exclude: Vec<String>,

        /// Enable verbose logging
        #[arg(long, short)]
        verbose: bool,

        /// Fail if metrics exceed threshold (e.g., "dead_code_ratio=0.05")
        #[arg(long)]
        threshold: Option<String>,

        /// Write output to file instead of stdout
        #[arg(long, short)]
        output: Option<PathBuf>,
    },
    /// Generate a timeline of metrics for a file
    Timeline {
        /// Path to the file to analyze
        file: PathBuf,

        /// Start date for the timeline (e.g., "2023-01-01")
        #[arg(long)]
        since: Option<String>,
    },
    Compare(CompareCommand),
}

#[derive(Subcommand)]
enum ConfigSubcommand {
    /// Initialize a new .code-viz.toml configuration file
    Init,
}

#[tokio::main]
async fn main() -> anyhow::Result<()> {
    let cli = Cli::parse();

    match cli.command {
        Commands::Analyze {
            path,
            format,
            exclude,
            verbose,
            threshold,
            output,
            baseline,
            dead_code,
            duplicates,
            min_duplicate_lines,
            ai_commits,
            hotspots,
            max_hotspots,
            coverage_report,
        } => {
            let ctx = CliContext::new(verbose);
            let fs = RealFileSystem::new();
            let git = RealGit::new();

            commands::analyze::run(commands::analyze::AnalyzeConfig {
                path,
                format,
                exclude,
                verbose,
                threshold,
                output,
                baseline,
                dead_code,
                duplicates,
                min_duplicate_lines,
                ai_commits,
                hotspots,
                max_hotspots,
                coverage_report,
            }, ctx, fs, git).await?;
        }
        Commands::Watch {
            path,
            format,
            verbose,
        } => {
            let ctx = CliContext::new(verbose);
            let fs = RealFileSystem::new();
            commands::watch::run(path, format, verbose, ctx, fs).await?;
        }
        Commands::Diff { old, new } => {
            let fs = RealFileSystem::new();
            commands::diff::run(old, new, fs)?;
        }
        Commands::Config { subcommand } => match subcommand {
            ConfigSubcommand::Init => {
                let fs = RealFileSystem::new();
                commands::config::run_init(fs)?;
            }
        },
        Commands::DeadCode {
            path,
            format,
            min_confidence,
            exclude: _,
            verbose,
            threshold,
            output,
        } => {
            let ctx = CliContext::new(verbose);
            let fs = RealFileSystem::new();
            let git = RealGit::new();

            let config = commands::dead_code::DeadCodeConfig {
                path,
                format,
                min_confidence,
                verbose,
                threshold,
                output,
            };
            commands::dead_code::run(config, ctx, fs, git).await?;
        }
        Commands::Timeline { file, since } => {
            let git = RealGit::new();
            commands::timeline::run(file, since, git).await?;
        }
        Commands::Compare(args) => {
            commands::compare::handle_compare(&args).await?;
        }
    }

    Ok(())
}

use super::{FormatterError, MetricsFormatter};
use code_viz_core::AnalysisResult;
use csv::WriterBuilder;

pub struct CsvFormatter;

impl MetricsFormatter for CsvFormatter {
    fn format(&self, result: &AnalysisResult) -> Result<String, FormatterError> {
        let mut wtr = WriterBuilder::new().from_writer(vec![]);

        // Check if any file has dead code metrics
        let has_dead_code = result.files.iter().any(|f| f.dead_code_ratio.is_some());

        // Write header
        let header = if has_dead_code {
            vec!["path", "language", "loc", "functions", "size_bytes", "dead_functions", "dead_loc", "dead_code_ratio"]
        } else {
            vec!["path", "language", "loc", "functions", "size_bytes"]
        };
        wtr.write_record(&header)
            .map_err(|_| FormatterError::FormattingFailed)?;

        for file in &result.files {
            let mut record = vec![
                file.path.to_string_lossy().to_string(),
                file.language.clone(),
                file.loc.to_string(),
                file.function_count.to_string(),
                file.size_bytes.to_string(),
            ];

            if has_dead_code {
                record.push(file.dead_function_count.map_or_else(|| "0".to_string(), |v| v.to_string()));
                record.push(file.dead_code_loc.map_or_else(|| "0".to_string(), |v| v.to_string()));
                record.push(file.dead_code_ratio.map_or_else(|| "0.0".to_string(), |v| format!("{:.4}", v)));
            }

            wtr.write_record(&record)
                .map_err(|_| FormatterError::FormattingFailed)?;
        }

        let data = wtr.into_inner().map_err(|_| FormatterError::FormattingFailed)?;
        String::from_utf8(data).map_err(|_| FormatterError::FormattingFailed)
    }
}

use code_viz_dead_code::DeadCodeResult;
use code_viz_dead_code::models::SymbolKind;
use colored::*;
use serde_json;
use std::fmt::Write;

#[allow(dead_code)]
#[derive(Debug)]
pub enum DeadCodeFormatterError {
    JsonSerializationFailed,
    TextFormattingFailed,
}

impl std::fmt::Display for DeadCodeFormatterError {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        match self {
            Self::JsonSerializationFailed => write!(f, "Failed to serialize to JSON"),
            Self::TextFormattingFailed => write!(f, "Failed to format text output"),
        }
    }
}

impl std::error::Error for DeadCodeFormatterError {}

/// Trait for formatting dead code analysis results
pub trait DeadCodeFormatter {
    fn format(&self, result: &DeadCodeResult) -> Result<String, DeadCodeFormatterError>;
}

/// JSON formatter for dead code results
pub struct JsonFormatter;

impl DeadCodeFormatter for JsonFormatter {
    fn format(&self, result: &DeadCodeResult) -> Result<String, DeadCodeFormatterError> {
        serde_json::to_string_pretty(result)
            .map_err(|_| DeadCodeFormatterError::JsonSerializationFailed)
    }
}

/// Text formatter for human-readable output
pub struct TextFormatter;

impl DeadCodeFormatter for TextFormatter {
    fn format(&self, result: &DeadCodeResult) -> Result<String, DeadCodeFormatterError> {
        let mut output = String::new();
        format_header(&mut output)?;
        format_summary(&mut output, result)?;
        format_top_files(&mut output, result)?;
        format_confidence_breakdown(&mut output, result)?;
        format_detailed_files(&mut output, result)?;
        Ok(output)
    }
}

/// Format dead code result as pretty-printed JSON
#[allow(dead_code)]
pub fn format_json(result: &DeadCodeResult) -> Result<String, DeadCodeFormatterError> {
    JsonFormatter.format(result)
}

/// Format dead code result as human-readable text with colors
#[allow(dead_code)]
pub fn format_text(result: &DeadCodeResult) -> Result<String, DeadCodeFormatterError> {
    TextFormatter.format(result)
}

fn format_header(output: &mut String) -> Result<(), DeadCodeFormatterError> {
    writeln!(output, "\n{}", "Dead Code Analysis Summary".bold())
        .map_err(|_| DeadCodeFormatterError::TextFormattingFailed)?;
    writeln!(output, "{}", "=".repeat(50))
        .map_err(|_| DeadCodeFormatterError::TextFormattingFailed)
}

fn format_summary(output: &mut String, result: &DeadCodeResult) -> Result<(), DeadCodeFormatterError> {
    let summary = &result.summary;

    writeln!(output, "Total files analyzed:     {}", summary.total_files)
        .map_err(|_| DeadCodeFormatterError::TextFormattingFailed)?;

    let files_percentage = if summary.total_files > 0 {
        (summary.files_with_dead_code as f64 / summary.total_files as f64) * 100.0
    } else {
        0.0
    };
    writeln!(output, "Files with dead code:     {} ({:.1}%)", summary.files_with_dead_code, files_percentage)
        .map_err(|_| DeadCodeFormatterError::TextFormattingFailed)?;

    writeln!(output, "Total dead code:          {} LOC ({:.1}%)", summary.total_dead_loc, summary.dead_code_ratio * 100.0)
        .map_err(|_| DeadCodeFormatterError::TextFormattingFailed)?;

    writeln!(output, "Dead functions:           {}", summary.dead_functions)
        .map_err(|_| DeadCodeFormatterError::TextFormattingFailed)?;

    writeln!(output, "Dead classes:             {}", summary.dead_classes)
        .map_err(|_| DeadCodeFormatterError::TextFormattingFailed)?;

    let high_confidence_count = result.files.iter()
        .flat_map(|f| &f.dead_code)
        .filter(|s| s.confidence >= 90)
        .count();

    writeln!(output, "{}", format!("High-confidence deletions: {}", high_confidence_count).green())
        .map_err(|_| DeadCodeFormatterError::TextFormattingFailed)
}

fn format_top_files(output: &mut String, result: &DeadCodeResult) -> Result<(), DeadCodeFormatterError> {
    if result.files.is_empty() {
        return Ok(());
    }

    writeln!(output, "\n{}", "Top files by dead code:".bold())
        .map_err(|_| DeadCodeFormatterError::TextFormattingFailed)?;

    let mut files_sorted: Vec<_> = result.files.iter().collect();
    files_sorted.sort_by(|a, b| {
        let a_loc: usize = a.dead_code.iter().map(|s| s.loc).sum();
        let b_loc: usize = b.dead_code.iter().map(|s| s.loc).sum();
        b_loc.cmp(&a_loc)
    });

    for (i, file) in files_sorted.iter().take(10).enumerate() {
        let total_dead_loc: usize = file.dead_code.iter().map(|s| s.loc).sum();
        let symbol_count = file.dead_code.len();
        writeln!(output, "  {}. {} - {} LOC ({} symbols)", i + 1, file.path.display(), total_dead_loc, symbol_count)
            .map_err(|_| DeadCodeFormatterError::TextFormattingFailed)?;
    }

    Ok(())
}

fn format_confidence_breakdown(output: &mut String, result: &DeadCodeResult) -> Result<(), DeadCodeFormatterError> {
    writeln!(output, "\n{}", "Confidence Breakdown:".bold())
        .map_err(|_| DeadCodeFormatterError::TextFormattingFailed)?;

    let all_symbols: Vec<_> = result.files.iter().flat_map(|f| &f.dead_code).collect();
    let high_conf = all_symbols.iter().filter(|s| s.confidence >= 90).count();
    let medium_conf = all_symbols.iter().filter(|s| s.confidence >= 70 && s.confidence < 90).count();
    let low_conf = all_symbols.iter().filter(|s| s.confidence < 70).count();

    writeln!(output, "  {} High (≥90):   {} symbols", "●".green(), high_conf)
        .map_err(|_| DeadCodeFormatterError::TextFormattingFailed)?;
    writeln!(output, "  {} Medium (70-89): {} symbols", "●".yellow(), medium_conf)
        .map_err(|_| DeadCodeFormatterError::TextFormattingFailed)?;
    writeln!(output, "  {} Low (<70):    {} symbols", "●".red(), low_conf)
        .map_err(|_| DeadCodeFormatterError::TextFormattingFailed)
}

fn format_detailed_files(output: &mut String, result: &DeadCodeResult) -> Result<(), DeadCodeFormatterError> {
    if result.files.is_empty() {
        return Ok(());
    }

    writeln!(output, "\n{}", "Dead Code by File:".bold())
        .map_err(|_| DeadCodeFormatterError::TextFormattingFailed)?;

    for file in &result.files {
        writeln!(output, "\n  {}", file.path.display().to_string().cyan())
            .map_err(|_| DeadCodeFormatterError::TextFormattingFailed)?;

        let mut symbols_sorted = file.dead_code.clone();
        symbols_sorted.sort_by(|a, b| b.confidence.cmp(&a.confidence));

        for symbol in symbols_sorted {
            let confidence_colored = colorize_confidence(symbol.confidence);
            let kind_str = format_symbol_kind(symbol.kind);

            writeln!(
                output,
                "    {} {} (lines {}-{}, {} LOC, confidence: {})",
                kind_str,
                symbol.symbol.bold(),
                symbol.line_start,
                symbol.line_end,
                symbol.loc,
                confidence_colored
            )
            .map_err(|_| DeadCodeFormatterError::TextFormattingFailed)?;

            if !symbol.reason.is_empty() {
                writeln!(output, "      Reason: {}", symbol.reason.dimmed())
                    .map_err(|_| DeadCodeFormatterError::TextFormattingFailed)?;
            }
        }
    }

    Ok(())
}

/// Colorize confidence score based on thresholds
#[allow(dead_code)]
fn colorize_confidence(confidence: u8) -> String {
    let conf_str = format!("{}%", confidence);
    if confidence >= 90 {
        conf_str.green().to_string()
    } else if confidence >= 70 {
        conf_str.yellow().to_string()
    } else {
        conf_str.red().to_string()
    }
}

/// Format symbol kind as human-readable string
#[allow(dead_code)]
fn format_symbol_kind(kind: SymbolKind) -> &'static str {
    match kind {
        SymbolKind::Function => "fn",
        SymbolKind::ArrowFunction => "=>",
        SymbolKind::Class => "class",
        SymbolKind::Method => "method",
        SymbolKind::Variable => "var",
    }
}

