    }

    pub fn run(
        &self,
        files: &[(PathBuf, String)],
        parsers: &HashMap<String, Box<dyn LanguageParser>>,
    ) -> DuplicationAnalysis {
        let all_blocks = self.extract_blocks(files, parsers);
        let duplicate_pairs = self.find_duplicates(&all_blocks);
        let total_duplicated_loc = self.calculate_total_duplicated_loc(&duplicate_pairs);

        DuplicationAnalysis {
            pairs: duplicate_pairs,
            total_duplicated_loc,
        }
    }

    fn extract_blocks(
        &self,
        files: &[(PathBuf, String)],
        parsers: &HashMap<String, Box<dyn LanguageParser>>,
    ) -> Vec<CodeBlock> {
        files
            .iter()
            .flat_map(|(path, content)| {
                let language = path.extension().and_then(|s| s.to_str()).unwrap_or("");
                if let Some(parser) = parsers.get(language) {
                    // Skip files that fail to parse rather than crashing the entire analysis
                    self.parse_file(path, content, parser.as_ref()).unwrap_or_else(|e| {
                        eprintln!("Warning: Failed to parse {:?} for duplication analysis: {}", path, e);
                        vec![]
                    })
                } else {
                    vec![]
                }
            })
            .collect()
    }

    fn parse_file(&self, path: &Path, content: &str, parser: &dyn LanguageParser) -> Result<Vec<CodeBlock>> {
        let mut tree_sitter_parser = Parser::new();
        tree_sitter_parser
            .set_language(parser.get_language())
            .map_err(|e| CodeVizError::parse(
                path.to_path_buf(),
                "unknown",
                None,
                format!("Failed to set tree-sitter language: {:?}", e)
            ))?;

        let tree = tree_sitter_parser.parse(content, None)
            .ok_or_else(|| CodeVizError::parse(
                path.to_path_buf(),
                "unknown",
                None,
                "Failed to parse file - tree-sitter returned None"
            ))?;

        Ok(self.extract_blocks_from_tree(path, content, &tree))
    }

    fn extract_blocks_from_tree(&self, path: &Path, content: &str, tree: &Tree) -> Vec<CodeBlock> {
        let mut blocks = Vec::new();
        let mut queue = vec![tree.root_node()];

        while let Some(node) = queue.pop() {
            if node.kind() == "function_item"
                || node.kind() == "function_declaration"
                || node.kind() == "method_declaration"
            {
                let start_line = node.start_position().row + 1;
                let end_line = node.end_position().row + 1;
                let line_count = end_line - start_line;

                if line_count >= self.min_lines {
                    let canonical_text = self.canonicalize_node(node, content);
                    let hash = format!("{:x}", md5::compute(canonical_text.as_bytes()));
                    let location = CodeLocation {
                        path: path.to_path_buf(),
                        start_line,
                        end_line,
                    };
                    blocks.push(CodeBlock {
                        location,
                        hash,
                        canonical_text,
                        line_count,
                    });
                    continue;
                }
            }

            for i in (0..node.child_count()).rev() {
                if let Some(child) = node.child(i) {
                    queue.push(child);
                }
                // If child is None, skip it - this shouldn't happen but we handle it gracefully
            }
        }
        blocks
    }

    fn canonicalize_node(&self, node: Node, content: &str) -> String {
        let mut canonical_text = String::new();
        let mut queue = vec![node];

        while let Some(current_node) = queue.pop() {
            let kind = current_node.kind();
            if kind == "comment" || kind == "identifier" {
                continue;
            }

            if current_node.child_count() == 0 {
                // It's a leaf node (a token), use its text content.
                // If we can't get valid UTF-8, skip this node
                if let Ok(text) = current_node.utf8_text(content.as_bytes()) {
                    canonical_text.push_str(text);
                    canonical_text.push(' ');
                }
            } else {
                // It's an internal node, use its kind to represent structure.
                canonical_text.push_str(kind);
                canonical_text.push(' ');
            }
            // push children in reverse order to process them in forward order (DFS)
            for i in (0..current_node.child_count()).rev() {
                if let Some(child) = current_node.child(i) {
                    queue.push(child);
                }
            }
        }
        canonical_text
    }

    fn find_duplicates(&self, blocks: &[CodeBlock]) -> Vec<DuplicatePair> {
        let blocks_by_hash = self.group_blocks_by_hash(blocks);

        let mut pairs = self.find_exact_duplicates(&blocks_by_hash);

        let similar_pairs = self.find_similar_duplicates(&blocks_by_hash);
        pairs.extend(similar_pairs);

        pairs
    }

    fn group_blocks_by_hash<'a>(
        &self,
        blocks: &'a [CodeBlock],
    ) -> HashMap<String, Vec<&'a CodeBlock>> {
        let mut blocks_by_hash: HashMap<String, Vec<&CodeBlock>> = HashMap::new();
        for block in blocks {
            if !block.hash.is_empty() {
                blocks_by_hash
                    .entry(block.hash.clone())
                    .or_default()
                    .push(block);
            }
        }
        blocks_by_hash
    }

    fn find_exact_duplicates(
        &self,
        blocks_by_hash: &HashMap<String, Vec<&CodeBlock>>,
    ) -> Vec<DuplicatePair> {
        let mut pairs = Vec::new();

        for duplicated_blocks in blocks_by_hash.values().filter(|v| v.len() > 1) {
            for i in 0..duplicated_blocks.len() {
                for j in i + 1..duplicated_blocks.len() {
                    let block_a = duplicated_blocks[i];
                    let block_b = duplicated_blocks[j];
                    pairs.push(DuplicatePair {
                        original: block_a.location.clone(),
                        duplicate: block_b.location.clone(),
                        similarity: 1.0,
                        line_count: block_a.line_count,
                    });
                }
            }
        }

        pairs
    }

    fn find_similar_duplicates(
        &self,
        blocks_by_hash: &HashMap<String, Vec<&CodeBlock>>,
    ) -> Vec<DuplicatePair> {
        let mut pairs = Vec::new();
        let unique_blocks: Vec<&CodeBlock> = blocks_by_hash.values().map(|v| v[0]).collect();

        for i in 0..unique_blocks.len() {
            for j in i + 1..unique_blocks.len() {
                let block_a = unique_blocks[i];
                let block_b = unique_blocks[j];

                if let Some(similarity) = self.calculate_similarity(block_a, block_b) {
                    if similarity >= self.similarity_threshold {
                        let new_pairs = self.create_pairs_for_similar_groups(
                            block_a,
                            block_b,
                            similarity,
                            blocks_by_hash,
                        );
                        pairs.extend(new_pairs);
                    }
                }
            }
        }

        pairs
    }

    fn calculate_similarity(&self, block_a: &CodeBlock, block_b: &CodeBlock) -> Option<f64> {
        let len_a = block_a.canonical_text.len();
        let len_b = block_b.canonical_text.len();

        if len_a == 0 || len_b == 0 {
            return None;
        }

        let distance =
            levenshtein::levenshtein(&block_a.canonical_text, &block_b.canonical_text);
        let max_len = std::cmp::max(len_a, len_b) as f64;
        let similarity = 1.0 - (distance as f64 / max_len);

        Some(similarity)
    }

    fn create_pairs_for_similar_groups(
        &self,
        block_a: &CodeBlock,
        block_b: &CodeBlock,
        similarity: f64,
        blocks_by_hash: &HashMap<String, Vec<&CodeBlock>>,
    ) -> Vec<DuplicatePair> {
        let mut pairs = Vec::new();

        if let (Some(blocks_a), Some(blocks_b)) =
            (blocks_by_hash.get(&block_a.hash), blocks_by_hash.get(&block_b.hash))
        {
            for ba in blocks_a {
                for bb in blocks_b {
                    pairs.push(DuplicatePair {
                        original: ba.location.clone(),
                        duplicate: bb.location.clone(),
                        similarity,
                        line_count: ba.line_count,
                    });
                }
            }
        }

        pairs
    }

    fn calculate_total_duplicated_loc(&self, pairs: &[DuplicatePair]) -> usize {
        let mut duplicated_lines = HashSet::new();
        for pair in pairs {
            for line in pair.original.start_line..=pair.original.end_line {
                duplicated_lines.insert((pair.original.path.clone(), line));
            }
            for line in pair.duplicate.start_line..=pair.duplicate.end_line {
                duplicated_lines.insert((pair.duplicate.path.clone(), line));
            }
        }
        duplicated_lines.len()
    }
}

//! Unified error handling for code-viz
//!
//! This module provides a centralized error type hierarchy for the entire code-viz project,
//! replacing scattered unwrap() calls with proper error propagation.
//!
//! # Error Types
//!
//! The main error type is [`CodeVizError`], which wraps all specific error variants:
//!
//! - [`ParseError`] - Parsing failures (tree-sitter, malformed code)
//! - [`FileSystem`] - File I/O operations (reading, writing, permissions)
//! - [`Git`] - Git operations (repository access, commit history)
//! - [`Analysis`] - Analysis failures (metrics calculation, dependency detection)
//! - [`Coverage`] - Coverage data issues (missing data, malformed LCOV)
//! - [`Cache`] - Cache operations (serialization, storage)
//!
//! # Usage
//!
//! ## Basic error propagation with `?`
//!
//! ```rust,no_run
//! use code_viz_core::error::{CodeVizError, Result};
//! use std::path::Path;
//!
//! fn read_and_parse(path: &Path) -> Result<String> {
//!     let content = std::fs::read_to_string(path)
//!         .map_err(|e| CodeVizError::file_read(path, e))?;
//!     Ok(content)
//! }
//! ```
//!
//! ## Adding context to errors
//!
//! ```rust,no_run
//! use code_viz_core::error::{CodeVizError, Result};
//!
//! fn analyze_file(path: &str) -> Result<()> {
//!     parse_file(path)
//!         .map_err(|e| e.context(format!("analyzing file: {}", path)))?;
//!     Ok(())
//! }
//! # fn parse_file(path: &str) -> Result<()> { Ok(()) }
//! ```

use std::io;
use std::path::PathBuf;
use thiserror::Error;

/// Result type alias using [`CodeVizError`]
pub type Result<T> = std::result::Result<T, CodeVizError>;

/// Unified error type for code-viz operations
///
/// This error type consolidates all error conditions that can occur during
/// code analysis, providing rich context and proper error chaining.
#[derive(Debug, Error)]
pub enum CodeVizError {
    /// Parse error occurred while analyzing source code
    ///
    /// This variant captures parsing failures from tree-sitter or other
    /// language parsers. It includes the file path, programming language,
    /// line number (if available), and the underlying error.
    ///
    /// # Example
    ///
    /// ```rust
    /// use code_viz_core::error::CodeVizError;
    /// use std::path::PathBuf;
    ///
    /// let error = CodeVizError::parse(
    ///     PathBuf::from("src/main.rs"),
    ///     "rust",
    ///     Some(42),
    ///     "unexpected token",
    /// );
    /// ```
    #[error("Parse error in {language} file {path:?} at line {line:?}: {message}")]
    ParseError {
        /// Path to the file that failed to parse
        path: PathBuf,
        /// Programming language being parsed
        language: String,
        /// Line number where the error occurred (if known)
        line: Option<usize>,
        /// Detailed error message
        message: String,
    },

    /// File system operation failed
    ///
    /// Covers all file I/O errors including:
    /// - File not found
    /// - Permission denied
    /// - Disk full
    /// - Invalid paths
    ///
    /// The source error from `std::io::Error` is preserved for detailed diagnostics.
    #[error("File system error at {path:?}: {message}")]
    FileSystem {
        /// Path where the error occurred
        path: PathBuf,
        /// Human-readable description
        message: String,
        /// Original I/O error
        #[source]
        source: io::Error,
    },

    /// Git operation failed
    ///
    /// Used when git operations fail, such as:
    /// - Repository not found
    /// - Invalid commit reference
    /// - Failed to read commit history
    #[error("Git error in repository {repository:?}: {message}")]
    Git {
        /// Repository path
        repository: Option<PathBuf>,
        /// Error description
        message: String,
    },

    /// Analysis operation failed
    ///
    /// Covers failures during code analysis including:
    /// - Metrics calculation errors
    /// - Dependency graph building failures
    /// - Coupling analysis errors
    /// - Dead code detection failures
    #[error("Analysis failed: {operation} - {message}")]
    Analysis {
        /// The analysis operation that failed (e.g., "coupling", "metrics")
        operation: String,
        /// Detailed error message
        message: String,
        /// Optional file path being analyzed
        path: Option<PathBuf>,
    },

    /// Coverage data error
    ///
    /// Used when coverage data is missing, malformed, or cannot be processed.
    /// This is often a non-critical error that can be handled with defaults.
    #[error("Coverage data error: {message}")]
    CoverageDataMissing {
        /// Description of the coverage issue
        message: String,
        /// Path to the coverage file (if applicable)
        path: Option<PathBuf>,
    },

    /// Cache operation failed
    ///
    /// Errors related to caching analysis results, including:
    /// - Serialization failures
    /// - Cache corruption
    /// - Storage errors
    #[error("Cache error: {message}")]
    Cache {
        /// Error description
        message: String,
        /// Underlying error if available
        #[source]
        source: Option<Box<dyn std::error::Error + Send + Sync>>,
    },

    /// Configuration error
    ///
    /// Invalid or missing configuration values
    #[error("Configuration error: {message}")]
    Config {
        /// What configuration is invalid
        message: String,
    },
}

impl CodeVizError {
    // Convenience constructors for common error patterns

    /// Create a parse error
    ///
    /// # Arguments
    ///
    /// * `path` - File path that failed to parse
    /// * `language` - Programming language
    /// * `line` - Optional line number
    /// * `message` - Error description
    pub fn parse(path: PathBuf, language: impl Into<String>, line: Option<usize>, message: impl Into<String>) -> Self {
        Self::ParseError {
            path,
            language: language.into(),
            line,
            message: message.into(),
        }
    }

    /// Create a file read error
    ///
    /// # Arguments
    ///
    /// * `path` - Path that could not be read
    /// * `source` - Original I/O error
    pub fn file_read(path: impl Into<PathBuf>, source: io::Error) -> Self {
        let path = path.into();
        Self::FileSystem {
            message: "Failed to read file".to_string(),
            path,
            source,
        }
    }

    /// Create a file write error
    ///
    /// # Arguments
    ///
    /// * `path` - Path that could not be written
    /// * `source` - Original I/O error
    pub fn file_write(path: impl Into<PathBuf>, source: io::Error) -> Self {
        let path = path.into();
        Self::FileSystem {
            message: "Failed to write file".to_string(),
            path,
            source,
        }
    }

    /// Create a git error
    ///
    /// # Arguments
    ///
    /// * `repository` - Optional repository path
    /// * `message` - Error description
    pub fn git(repository: Option<PathBuf>, message: impl Into<String>) -> Self {
        Self::Git {
            repository,
            message: message.into(),
        }
    }

    /// Create an analysis error
    ///
    /// # Arguments
    ///
    /// * `operation` - Name of the analysis operation
    /// * `message` - Error description
    pub fn analysis(operation: impl Into<String>, message: impl Into<String>) -> Self {
        Self::Analysis {
            operation: operation.into(),
            message: message.into(),
            path: None,
        }
    }

    /// Create an analysis error with a file path
    ///
    /// # Arguments
    ///
    /// * `operation` - Name of the analysis operation
    /// * `path` - File being analyzed
    /// * `message` - Error description
    pub fn analysis_with_path(
        operation: impl Into<String>,
        path: impl Into<PathBuf>,
        message: impl Into<String>,
    ) -> Self {
        Self::Analysis {
            operation: operation.into(),
            message: message.into(),
            path: Some(path.into()),
        }
    }

    /// Create a coverage data missing error
    ///
    /// # Arguments
    ///
    /// * `message` - Description of what's missing
    pub fn coverage_missing(message: impl Into<String>) -> Self {
        Self::CoverageDataMissing {
            message: message.into(),
            path: None,
        }
    }

    /// Create a cache error
    ///
    /// # Arguments
    ///
    /// * `message` - Error description
    pub fn cache(message: impl Into<String>) -> Self {
        Self::Cache {
            message: message.into(),
            source: None,
        }
    }

    /// Create a cache error with a source error
    ///
    /// # Arguments
    ///
    /// * `message` - Error description
    /// * `source` - Underlying error
    pub fn cache_with_source(
        message: impl Into<String>,
        source: impl std::error::Error + Send + Sync + 'static,
    ) -> Self {
        Self::Cache {
            message: message.into(),
            source: Some(Box::new(source)),
        }
    }

    /// Create a configuration error
    ///
    /// # Arguments
    ///
    /// * `message` - What configuration is invalid
    pub fn config(message: impl Into<String>) -> Self {
        Self::Config {
            message: message.into(),
        }
    }

    /// Add context to this error
    ///
    /// This is useful for adding higher-level context when propagating errors
    /// up the call stack.
    ///
    /// # Example
    ///
    /// ```rust
    /// use code_viz_core::error::CodeVizError;
    ///
    /// fn process_file(path: &str) -> code_viz_core::error::Result<()> {
    ///     read_file(path)
    ///         .map_err(|e| e.context(format!("processing {}", path)))?;
    ///     Ok(())
    /// }
    /// # fn read_file(path: &str) -> code_viz_core::error::Result<()> { Ok(()) }
    /// ```
    pub fn context(self, _context: impl Into<String>) -> Self {
        // For now, just return self. In the future, we could wrap the error
        // in a context variant or append to the message.
        // This provides a forward-compatible API.
        self
    }
}

// Automatic conversions from common error types

impl From<io::Error> for CodeVizError {
    fn from(err: io::Error) -> Self {
        Self::FileSystem {
            path: PathBuf::from("<unknown>"),
            message: "I/O operation failed".to_string(),
            source: err,
        }
    }
}

impl From<crate::parser::ParseError> for CodeVizError {
    fn from(err: crate::parser::ParseError) -> Self {
        Self::ParseError {
            path: PathBuf::from("<unknown>"),
            language: "unknown".to_string(),
            line: None,
            message: err.to_string(),
        }
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn test_parse_error_creation() {
        let error = CodeVizError::parse(
            PathBuf::from("src/main.rs"),
            "rust",
            Some(42),
            "unexpected token",
        );

        let error_msg = error.to_string();
        assert!(error_msg.contains("src/main.rs"));
        assert!(error_msg.contains("rust"));
        assert!(error_msg.contains("42"));
        assert!(error_msg.contains("unexpected token"));
    }

    #[test]
    fn test_file_read_error() {
        let io_err = io::Error::new(io::ErrorKind::NotFound, "file not found");
        let error = CodeVizError::file_read(PathBuf::from("missing.txt"), io_err);

        let error_msg = error.to_string();
        assert!(error_msg.contains("missing.txt"));
        assert!(error_msg.contains("Failed to read file"));
    }

    #[test]
    fn test_analysis_error() {
        let error = CodeVizError::analysis("coupling", "failed to build graph");
        let error_msg = error.to_string();
        assert!(error_msg.contains("coupling"));
        assert!(error_msg.contains("failed to build graph"));
    }

    #[test]
    fn test_from_io_error() {
        let io_err = io::Error::new(io::ErrorKind::PermissionDenied, "access denied");
        let error: CodeVizError = io_err.into();

        match error {
            CodeVizError::FileSystem { .. } => (),
            _ => panic!("Expected FileSystem error"),
        }
    }

    #[test]
    fn test_error_implements_std_error() {
        let error = CodeVizError::analysis("test", "test error");
        // This will fail to compile if CodeVizError doesn't implement std::error::Error
        let _: &dyn std::error::Error = &error;
    }

    #[test]
    fn test_context_method() {
        let error = CodeVizError::analysis("test", "original error");
        let with_context = error.context("additional context");

        // Context should preserve the error
        assert!(with_context.to_string().contains("original error"));
    }
}

//! Error conversion utilities and extensions
//!
//! This module provides ergonomic helpers to reduce error mapping boilerplate
//! throughout the codebase. It includes extension traits for `Result` types
//! and convenience macros for common error conversions.
//!
//! # Examples
//!
//! ## Using ResultExt for context
//!
//! ```rust
//! use code_viz_core::error_ext::ResultExt;
//! use std::fs;
//!
//! fn read_config() -> code_viz_core::error::Result<String> {
//!     fs::read_to_string("config.toml")
//!         .with_context(|| "reading configuration file")?;
//!     Ok("config".to_string())
//! }
//! ```
//!
//! ## Using macros for error conversion
//!
//! ```rust
//! use code_viz_core::{io_error, parse_error};
//! use std::path::PathBuf;
//!
//! # fn example() -> code_viz_core::error::Result<()> {
//! // Convert I/O errors with file context
//! let content = std::fs::read_to_string("file.txt")
//!     .map_err(|e| io_error!("file.txt", e))?;
//!
//! // Create parse errors with language context
//! let error = parse_error!("src/main.rs", "rust", 42, "unexpected token");
//! # Ok(())
//! # }
//! ```

use crate::error::{CodeVizError, Result};

/// Extension trait for `Result` types to add context to errors
///
/// This trait provides a convenient way to add contextual information
/// to errors as they propagate up the call stack, without needing
/// verbose `.map_err()` calls.
///
/// # Examples
///
/// ```rust
/// use code_viz_core::error_ext::ResultExt;
/// use code_viz_core::error::Result;
///
/// fn parse_file(path: &str) -> Result<String> {
///     read_file(path)
///         .with_context(|| format!("parsing file: {}", path))?;
///     Ok("parsed".to_string())
/// }
/// # fn read_file(path: &str) -> Result<String> { Ok("content".to_string()) }
/// ```
pub trait ResultExt<T> {
    /// Add contextual information to an error
    ///
    /// The context closure is only evaluated if the result is an error,
    /// making this efficient for the success path.
    ///
    /// # Arguments
    ///
    /// * `context` - A closure that returns contextual information as a String
    fn with_context<F>(self, context: F) -> Result<T>
    where
        F: FnOnce() -> String;
}

impl<T, E> ResultExt<T> for std::result::Result<T, E>
where
    E: Into<CodeVizError>,
{
    #[inline]
    fn with_context<F>(self, context: F) -> Result<T>
    where
        F: FnOnce() -> String,
    {
        self.map_err(|e| {
            let err: CodeVizError = e.into();
            err.context(context())
        })
    }
}

/// Convert an I/O error with file path context
///
/// # Examples
///
/// ```rust
/// use code_viz_core::io_error;
///
/// # fn example() -> code_viz_core::error::Result<()> {
/// let content = std::fs::read_to_string("config.toml")
///     .map_err(|e| io_error!("config.toml", e))?;
/// # Ok(())
/// # }
/// ```
#[macro_export]
macro_rules! io_error {
    ($path:expr, $source:expr) => {
        $crate::error::CodeVizError::file_read($path, $source)
    };
}

/// Create a parse error with full context
///
/// # Arguments
///
/// * `path` - File path
/// * `language` - Programming language
/// * `line` - Line number (or `None`)
/// * `message` - Error message
///
/// # Examples
///
/// ```rust
/// use code_viz_core::parse_error;
///
/// # fn example() -> code_viz_core::error::Result<()> {
/// let error = parse_error!(
///     "src/main.rs",
///     "rust",
///     Some(42),
///     "unexpected token"
/// );
/// # Ok(())
/// # }
/// ```
#[macro_export]
macro_rules! parse_error {
    ($path:expr, $language:expr, $line:expr, $message:expr) => {
        $crate::error::CodeVizError::parse(
            std::path::PathBuf::from($path),
            $language,
            $line,
            $message,
        )
    };
}

/// Create an analysis error with operation context
///
/// # Examples
///
/// ```rust
/// use code_viz_core::analysis_error;
///
/// # fn example() -> code_viz_core::error::Result<()> {
/// return Err(analysis_error!("coupling", "failed to build dependency graph"));
/// # }
/// ```
#[macro_export]
macro_rules! analysis_error {
    ($operation:expr, $message:expr) => {
        $crate::error::CodeVizError::analysis($operation, $message)
    };
}

