mod tests {
    use super::*;
    use std::io;
    use std::path::PathBuf;

    // NOTE: Test code uses unwrap() for test fixtures and assertions.
    // This is acceptable because:
    // 1. Test data is controlled and known to be valid
    // 2. Test failures (panics) are the desired outcome when setup fails
    // 3. Panics in tests provide clear failure points for debugging

    #[test]
    fn test_result_ext_with_context() {
        fn failing_function() -> std::result::Result<(), io::Error> {
            Err(io::Error::new(io::ErrorKind::NotFound, "not found"))
        }

        let result: Result<()> = failing_function().with_context(|| "test context".to_string());

        assert!(result.is_err());
        let err = result.unwrap_err();
        // The error should be converted to CodeVizError
        match err {
            CodeVizError::FileSystem { .. } => (),
            _ => panic!("Expected FileSystem error"),
        }
    }

    #[test]
    fn test_result_ext_success() {
        fn success_function() -> std::result::Result<i32, io::Error> {
            Ok(42)
        }

        let result: Result<i32> = success_function().with_context(|| "test context".to_string());

        assert!(result.is_ok());
        assert_eq!(result.unwrap(), 42);
    }

    #[test]
    fn test_io_error_macro() {
        let io_err = io::Error::new(io::ErrorKind::NotFound, "file not found");
        let error = io_error!("test.txt", io_err);

        let error_msg = error.to_string();
        assert!(error_msg.contains("test.txt"));
    }

    #[test]
    fn test_parse_error_macro() {
        let error = parse_error!("src/main.rs", "rust", Some(42), "syntax error");

        match error {
            CodeVizError::ParseError {
                path,
                language,
                line,
                message,
            } => {
                assert_eq!(path, PathBuf::from("src/main.rs"));
                assert_eq!(language, "rust");
                assert_eq!(line, Some(42));
                assert_eq!(message, "syntax error");
            }
            _ => panic!("Expected ParseError"),
        }
    }

    #[test]
    fn test_analysis_error_macro() {
        let error = analysis_error!("coupling", "graph build failed");

        match error {
            CodeVizError::Analysis {
                operation, message, ..
            } => {
                assert_eq!(operation, "coupling");
                assert_eq!(message, "graph build failed");
            }
            _ => panic!("Expected Analysis error"),
        }
    }

    #[test]
    fn test_macro_hygiene() {
        // Test that macros work with module paths
        let error = crate::io_error!(
            "test.txt",
            io::Error::new(io::ErrorKind::NotFound, "not found")
        );

        assert!(matches!(error, CodeVizError::FileSystem { .. }));
    }
}

use crate::models::{FileMetrics, Hotspot, HotspotAnalysis};

/// Weights for hotspot score calculation
const CHURN_WEIGHT: f64 = 0.4;
const COMPLEXITY_WEIGHT: f64 = 0.4;
const SIZE_WEIGHT: f64 = 0.2;

pub struct HotspotDetector {
    /// Maximum number of hotspots to return
    max_hotspots: usize,
}

impl HotspotDetector {
    pub fn new(max_hotspots: usize) -> Self {
        Self { max_hotspots }
    }

    fn calculate_max_values(files: &[&FileMetrics]) -> (f64, f64, f64) {
        let max_churn = files
            .iter()
            .filter_map(|f| {
                f.code_churn.as_ref().map(|churn| churn.added_lines + churn.deleted_lines)
            })
            .max()
            .unwrap_or(1) as f64;

        let max_complexity = files.iter().map(|f| f.function_count).max().unwrap_or(1) as f64;
        let max_size = files.iter().map(|f| f.loc).max().unwrap_or(1) as f64;

        (max_churn, max_complexity, max_size)
    }

    fn normalize_score(value: f64, max_value: f64) -> f64 {
        if max_value > 0.0 {
            value / max_value
        } else {
            0.0
        }
    }

    fn calculate_hotspot_for_file(
        file: &FileMetrics,
        max_churn: f64,
        max_complexity: f64,
        max_size: f64,
    ) -> Option<Hotspot> {
        let churn = file.code_churn.as_ref()?;
        let total_changes = churn.added_lines + churn.deleted_lines;

        let churn_score = Self::normalize_score(total_changes as f64, max_churn);
        let complexity_score = Self::normalize_score(file.function_count as f64, max_complexity);
        let size_score = Self::normalize_score(file.loc as f64, max_size);

        let hotspot_score = (churn_score * CHURN_WEIGHT)
            + (complexity_score * COMPLEXITY_WEIGHT)
            + (size_score * SIZE_WEIGHT);

        Some(Hotspot {
            path: file.path.clone(),
            hotspot_score,
            churn_score,
            complexity_score,
            size_score,
            total_changes,
        })
    }

    /// Calculate hotspot analysis from file metrics
    /// Requires files to have code_churn data populated
    pub fn calculate(&self, files: &[FileMetrics]) -> HotspotAnalysis {
        let files_with_churn: Vec<&FileMetrics> = files
            .iter()
            .filter(|f| f.code_churn.is_some())
            .collect();

        if files_with_churn.is_empty() {
            return HotspotAnalysis {
                hotspots: Vec::new(),
                total_files_analyzed: 0,
            };
        }

        let (max_churn, max_complexity, max_size) = Self::calculate_max_values(&files_with_churn);

        let mut hotspots: Vec<Hotspot> = files_with_churn
            .iter()
            .filter_map(|file| {
                Self::calculate_hotspot_for_file(file, max_churn, max_complexity, max_size)
            })
            .collect();

        hotspots.sort_by(|a, b| {
            b.hotspot_score
                .partial_cmp(&a.hotspot_score)
                .unwrap_or(std::cmp::Ordering::Less)
        });

        hotspots.truncate(self.max_hotspots);

        HotspotAnalysis {
            hotspots,
            total_files_analyzed: files_with_churn.len(),
        }
    }
}

#[cfg(test)]
mod tests {
    use super::*;
