        let metrics = calculate_metrics(&path, source, parser.as_ref(), None).unwrap();
        assert_eq!(metrics.loc, 1);
    }

    #[test]
    fn test_code_inside_comment_block() {
        // Checking boundaries
        let parser = get_parser("typescript").unwrap();
        let source = r#"
            let a = 1;
            /* start
            mid
            end */ let b = 2;
        "#;
        // 1. let a (LOC)
        // 2. /* start (Skip)
        // 3. mid (Skip)
        // 4. end */ let b (LOC)
        // Total: 2
        let temp_dir = TempDir::new().unwrap();
        let path = temp_dir.path().join("test.ts");
        let metrics = calculate_metrics(&path, source, parser.as_ref(), None).unwrap();
        assert_eq!(metrics.loc, 2);
    }

    #[test]
    fn test_function_count() {
        let parser = get_parser("typescript").unwrap();
        let source = "function a() {} function b() {}";
        let temp_dir = TempDir::new().unwrap();
        let path = temp_dir.path().join("test.ts");
        let metrics = calculate_metrics(&path, source, parser.as_ref(), None).unwrap();
        assert_eq!(metrics.function_count, 2);
    }

    #[test]
    fn test_file_metadata_defaults_to_now() {
        let parser = get_parser("typescript").unwrap();
        let temp_dir = TempDir::new().unwrap();
        let path = temp_dir.path().join("test.ts");
        let source = "let x = 1;";

        // When last_modified is None, it should default to now()
        let metrics = calculate_metrics(&path, source, parser.as_ref(), None).unwrap();
        assert_eq!(metrics.size_bytes, source.len() as u64);

        // last_modified should be close to now (within 1 second)
        let duration = SystemTime::now().duration_since(metrics.last_modified).unwrap();
        assert!(duration.as_secs() < 1);
    }

    #[test]
    fn test_file_metadata_with_provided_time() {
        let parser = get_parser("typescript").unwrap();
        let temp_dir = TempDir::new().unwrap();
        let path = temp_dir.path().join("test.ts");
        let source = "let x = 1;";

        // When last_modified is provided, it should use that value
        let provided_time = SystemTime::UNIX_EPOCH + std::time::Duration::from_secs(1000000);
        let metrics = calculate_metrics(&path, source, parser.as_ref(), Some(provided_time)).unwrap();

        assert_eq!(metrics.last_modified, provided_time);
    }

    #[test]
    fn test_ai_bloat_index_calculation() {
        let parser = get_parser("typescript").unwrap();
        let source = r#"
            // This is a comment
            let x = 1; // Another comment
        "#;
        // 2 non-blank lines, 1 LOC. So, 1 comment line.
        // (1 / 1) * 100 = 100
        let temp_dir = TempDir::new().unwrap();
        let path = temp_dir.path().join("test.ts");
        let metrics = calculate_metrics(&path, source, parser.as_ref(), None).unwrap();
        assert_eq!(metrics.ai_bloat_index, Some(100.0));
    }

    #[test]
    fn test_ai_bloat_index_zero_loc() {
        let parser = get_parser("typescript").unwrap();
        let source = "// Just a comment";
        // 1 non-blank line, 0 LOC. So, 1 comment line.
        // Should return 999.0
        let temp_dir = TempDir::new().unwrap();
        let path = temp_dir.path().join("test.ts");
        let metrics = calculate_metrics(&path, source, parser.as_ref(), None).unwrap();
        assert_eq!(metrics.ai_bloat_index, Some(999.0));
    }

    #[test]
    fn test_ai_bloat_index_no_comments() {
        let parser = get_parser("typescript").unwrap();
        let source = "let x = 1;";
        // 1 non-blank line, 1 LOC. 0 comment lines.
        // (0 / 1) * 100 = 0
        let temp_dir = TempDir::new().unwrap();
        let path = temp_dir.path().join("test.ts");
        let metrics = calculate_metrics(&path, source, parser.as_ref(), None).unwrap();
        assert_eq!(metrics.ai_bloat_index, Some(0.0));
    }

    #[test]
    fn test_ai_bloat_index_empty_file() {
        let parser = get_parser("typescript").unwrap();
        let source = "";
        // 0 non-blank lines, 0 LOC. 0 comment lines.
        // Should be 0.0
        let temp_dir = TempDir::new().unwrap();
        let path = temp_dir.path().join("test.ts");
        let metrics = calculate_metrics(&path, source, parser.as_ref(), None).unwrap();
        assert_eq!(metrics.ai_bloat_index, Some(0.0));
    }
}

use anyhow::Result;
use async_trait::async_trait;
use crate::traits::AppContext;
use serde_json::{json, Value};
use std::path::PathBuf;
use std::sync::{Arc, Mutex};

/// Mock implementation of AppContext for unit testing.
/// Captures emitted events in a thread-safe vector for later verification.
#[derive(Clone, Default)]
pub struct MockContext {
    events: Arc<Mutex<Vec<(String, Value)>>>,
    app_dir: Arc<Mutex<PathBuf>>,
}

impl MockContext {
    /// Create a new MockContext.
    pub fn new() -> Self {
        Self {
            events: Arc::new(Mutex::new(Vec::new())),
            app_dir: Arc::new(Mutex::new(std::env::temp_dir())),
        }
    }

    /// Set a specific app directory.
    pub fn with_app_dir(self, path: PathBuf) -> Self {
        *self.app_dir.lock().unwrap() = path;
        self
    }

    /// Get a clone of all captured events.
    pub fn get_events(&self) -> Vec<(String, Value)> {
        self.events.lock().unwrap().clone()
    }

    /// Get events by name.
    pub fn get_events_by_name(&self, event_name: &str) -> Vec<Value> {
        self.events.lock().unwrap().iter()
            .filter(|(name, _)| name == event_name)
            .map(|(_, payload)| payload.clone())
            .collect()
    }

    /// Assert that an event with the given name was emitted.
    /// Panics with a descriptive message if the event was not found.
    pub fn assert_event_emitted(&self, event_name: &str) {
        let events = self.get_events();
        assert!(
            events.iter().any(|(name, _)| name == event_name),
            "Expected event '{}' to be emitted, but it was not. Captured events: {:?}",
            event_name,
            events
        );
    }

    /// Clear all captured events.
    pub fn clear_events(&self) {
        self.events.lock().unwrap().clear();
    }
}

#[async_trait]
impl AppContext for MockContext {
    async fn emit_event(&self, event: &str, payload: Value) -> Result<()> {
        self.events.lock().unwrap().push((event.to_string(), payload));
        Ok(())
    }

    fn get_app_dir(&self) -> PathBuf {
        self.app_dir.lock().unwrap().clone()
    }

    async fn report_progress(&self, percentage: f32, message: &str) -> Result<()> {
        self.emit_event(
            "progress",
            json!({
                "percentage": percentage,
                "message": message
            }),
        )
        .await
    }
}

use anyhow::{anyhow, Result};
use crate::traits::FileSystem;
use std::collections::HashMap;
use std::path::{Path, PathBuf};
use std::sync::{Arc, Mutex};

/// Mock implementation of FileSystem for unit testing.
/// Uses an in-memory HashMap to store file contents and tracks all read operations.
#[derive(Clone, Default)]
pub struct MockFileSystem {
    files: Arc<Mutex<HashMap<PathBuf, String>>>,
    reads: Arc<Mutex<Vec<PathBuf>>>,
}

impl MockFileSystem {
    /// Create a new MockFileSystem.
    pub fn new() -> Self {
        Self {
            files: Arc::new(Mutex::new(HashMap::new())),
            reads: Arc::new(Mutex::new(Vec::new())),
        }
    }

    /// Add a file to the mock filesystem.
    pub fn with_file(self, path: impl Into<PathBuf>, content: impl Into<String>) -> Self {
        self.files.lock().unwrap().insert(path.into(), content.into());
        self
    }

    /// Add multiple files to the mock filesystem.
    pub fn with_files(self, files: HashMap<PathBuf, String>) -> Self {
        self.files.lock().unwrap().extend(files);
        self
    }

    /// Get all paths that were read.
    pub fn get_reads(&self) -> Vec<PathBuf> {
        self.reads.lock().unwrap().clone()
    }

    /// Assert that a specific path was read.
    pub fn assert_read(&self, path: &Path) {
        let reads = self.get_reads();
        assert!(
            reads.iter().any(|p| p == path),
            "Expected path '{}' to be read, but it was not. Captured reads: {:?}",
            path.display(),
            reads
        );
    }
}

impl FileSystem for MockFileSystem {
    fn read_to_string(&self, path: &Path) -> Result<String> {
        self.reads.lock().unwrap().push(path.to_path_buf());
        self.files.lock().unwrap().get(path)
            .cloned()
            .ok_or_else(|| anyhow!("File not found in mock filesystem: {}", path.display()))
    }

    fn read_dir_recursive(&self, path: &Path) -> Result<Vec<PathBuf>> {
        self.reads.lock().unwrap().push(path.to_path_buf());
        let files = self.files.lock().unwrap();
        let result: Vec<PathBuf> = files
            .keys()
            .filter(|p| p.starts_with(path))
            .cloned()
            .collect();
        Ok(result)
    }

    fn write(&self, path: &Path, content: &str) -> Result<()> {
        self.files.lock().unwrap().insert(path.to_path_buf(), content.to_string());
        Ok(())
    }

    fn exists(&self, path: &Path) -> bool {
        self.files.lock().unwrap().contains_key(path)
    }
}

use anyhow::{anyhow, Result};
use async_trait::async_trait;
use crate::traits::{BlameInfo, Commit, Diff, GitProvider};
use crate::traits::git_provider::ChangedFile;
use std::collections::HashMap;
use std::path::{Path, PathBuf};
use std::sync::{Arc, Mutex};

type DiffCall = (String, Option<String>, String);

/// Mock implementation of GitProvider for unit testing.
/// Provides a configurable commit history and tracks operations.
#[derive(Clone, Default)]
pub struct MockGit {
    commits: Arc<Mutex<Vec<Commit>>>,
    diffs: Arc<Mutex<Vec<DiffCall>>>,
    mock_diffs: Arc<Mutex<HashMap<PathBuf, Diff>>>,
    churn_summary: Arc<Mutex<HashMap<PathBuf, (usize, usize)>>>,
    blames: Arc<Mutex<Vec<BlameInfo>>>,
    diff_calls: Arc<Mutex<Vec<DiffCall>>>,
    mock_diff: Arc<Mutex<Option<Diff>>>,
    changed_files: Arc<Mutex<Vec<ChangedFile>>>,
    file_contents: Arc<Mutex<HashMap<(PathBuf, String), String>>>,
}

impl MockGit {
    /// Create a new MockGit.
    pub fn new() -> Self {
        Self {
            commits: Arc::new(Mutex::new(Vec::new())),
            diffs: Arc::new(Mutex::new(Vec::new())),
            mock_diffs: Arc::new(Mutex::new(HashMap::new())),
            churn_summary: Arc::new(Mutex::new(HashMap::new())),
            blames: Arc::new(Mutex::new(Vec::new())),
            diff_calls: Arc::new(Mutex::new(Vec::new())),
            mock_diff: Arc::new(Mutex::new(None)),
            changed_files: Arc::new(Mutex::new(Vec::new())),
            file_contents: Arc::new(Mutex::new(HashMap::new())),
        }
    }

    /// Add a commit to the mock history.
    pub fn with_commit(self, commit: Commit) -> Self {
        self.commits.lock().unwrap().push(commit);
        self
    }

    /// Add multiple commits to the mock history.
    pub fn with_commits(self, commits: Vec<Commit>) -> Self {
        self.commits.lock().unwrap().extend(commits);
        self
    }

    /// Set the default diff to be returned by get_diff.
    pub fn with_mock_diff(self, diff: Diff) -> Self {
        *self.mock_diff.lock().unwrap() = Some(diff);
        self
    }

    pub fn with_changed_files(self, files: Vec<ChangedFile>) -> Self {
        self.changed_files.lock().unwrap().extend(files);
        self
    }

    /// Helper to add a commit using simple parameters.
    pub fn add_commit(self, sha: &str, author: &str, message: &str) -> Self {
        self.with_commit(Commit {
            sha: sha.to_string(),
            author: author.to_string(),
            timestamp: 0,
            message: message.to_string(),
        })
    }

    /// Add a mock diff for a specific file path.
    pub fn with_diff_for_path(self, path: &str, diff: Diff) -> Self {
        self.mock_diffs
            .lock()
            .unwrap()
            .insert(PathBuf::from(path), diff);
        self
    }

    pub fn with_churn_summary(self, summary: HashMap<PathBuf, (usize, usize)>) -> Self {
        *self.churn_summary.lock().unwrap() = summary;
        self
    }

    /// Add blame information to the mock git provider.
    pub fn with_blame(self, blame: BlameInfo) -> Self {
        self.blames.lock().unwrap().push(blame);
        self
    }

    /// Add mock file content for a specific revision.
    pub fn with_file_content(self, sha: &str, path: &str, content: &str) -> Self {
        self.file_contents
            .lock()
            .unwrap()
            .insert((PathBuf::from(path), sha.to_string()), content.to_string());
        self
    }
}

#[async_trait]
impl GitProvider for MockGit {
    async fn get_history(&self, _path: &Path) -> Result<Vec<Commit>> {
        Ok(self.commits.lock().unwrap().clone())
    }

    async fn get_diff(&self, path: &Path, from: Option<&str>, to: &str) -> Result<Diff> {
        self.diff_calls.lock().unwrap().push((
            path.display().to_string(),
            from.map(|s| s.to_string()),
            to.to_string(),
        ));

        if let Some(diff) = self.mock_diff.lock().unwrap().clone() {
            Ok(diff)
        } else {
            Ok(Diff {
                added_lines: vec![],
                deleted_lines: vec![],
                modified_lines: vec![],
            })
        }
    }

    async fn get_blame(&self, file_path: &Path) -> Result<BlameInfo> {
        let blames = self.blames.lock().unwrap();
        let file_path_buf = file_path.to_path_buf();

        for blame in blames.iter() {
            if blame.file_path == file_path_buf {
                return Ok(blame.clone());
            }
        }

        Err(anyhow!(
            "No mock blame data found for file '{}'",
            file_path.display()
        ))
    }

    async fn get_churn_summary(
        &self,
        _path: &Path,
        _from: Option<&str>,
        _to: &str,
    ) -> Result<HashMap<PathBuf, (usize, usize)>> {
        Ok(self.churn_summary.lock().unwrap().clone())
    }

    async fn get_file_content_at_revision(&self, file_path: &Path, sha: &str) -> Result<String> {
        let key = (file_path.to_path_buf(), sha.to_string());
        let contents = self.file_contents.lock().unwrap();

        contents
            .get(&key)
            .cloned()
            .ok_or_else(|| anyhow!("Mock content not found for {}@{}", file_path.display(), sha))
    }

    async fn get_changed_files(&self, _base: &str, _head: &str) -> Result<Vec<ChangedFile>> {
        Ok(self.changed_files.lock().unwrap().clone())
    }
}

