//! Metric aggregation utilities for directory tree nodes
//!
//! This module provides functions for aggregating metrics (LOC, complexity, etc.)
//! from child nodes up to parent directories.

use crate::models::TreeNode;
use super::path_utils::get_parent_path;
use super::tree_builder::calculate_complexity;
use std::collections::HashMap;
use std::path::{Path, PathBuf};
use std::time::SystemTime;

/// Aggregates metrics (LOC, complexity) from children up to parent directories
///
/// This function performs a bottom-up traversal of the directory tree, aggregating
/// metrics from leaf nodes (files) up through parent directories to the root.
///
/// # Arguments
/// * `dir_map` - Mutable HashMap of path to TreeNode
/// * `root_path` - The root path of the tree
pub fn aggregate_directory_metrics(
    dir_map: &mut HashMap<PathBuf, TreeNode>,
    root_path: &Path,
) {
    // Collect all paths and sort by depth (deepest first) for bottom-up aggregation
    let mut paths: Vec<PathBuf> = dir_map.keys().cloned().collect();
    paths.sort_by(|a, b| {
        let depth_a = a.components().count();
        let depth_b = b.components().count();
        depth_b.cmp(&depth_a) // Sort descending by depth
    });

    // Process directories from deepest to shallowest
    for path in paths {
        if path == *root_path {
            continue; // Skip root in this loop, handle it last
        }

        // Calculate this directory's metrics from its children
        if let Some(dir_node) = dir_map.get(&path) {
            let (total_loc, max_modified, complexity) = aggregate_child_metrics(dir_node);

            // Update the directory node
            if let Some(dir_node_mut) = dir_map.get_mut(&path) {
                dir_node_mut.loc = total_loc;
                dir_node_mut.complexity = complexity;
                dir_node_mut.last_modified = max_modified;
            }

            // Now attach this directory to its parent
            attach_to_parent(dir_map, &path, root_path);
        }
    }

    // Finally, aggregate root node metrics
    aggregate_root_metrics(dir_map, root_path);
}

/// Aggregates metrics from a node's children
fn aggregate_child_metrics(node: &TreeNode) -> (usize, SystemTime, u32) {
    let total_loc: usize = node.children.iter().map(|c| c.loc).sum();
    let max_modified = node
        .children
        .iter()
        .map(|c| c.last_modified)
        .max()
        .unwrap_or(SystemTime::now());
    let complexity = calculate_complexity(total_loc);

    (total_loc, max_modified, complexity)
}

/// Attaches a directory node to its parent
fn attach_to_parent(
    dir_map: &mut HashMap<PathBuf, TreeNode>,
    path: &Path,
    root_path: &Path,
) {
    let parent_path = get_parent_path(path, root_path);
    if parent_path == *path {
        return; // Don't attach to self
    }

    // Clone the updated node
    if let Some(updated_node) = dir_map.get(path).cloned() {
        if let Some(parent) = dir_map.get_mut(&parent_path) {
            // Check if this child already exists in parent
            if !parent.children.iter().any(|c| c.path == *path) {
                parent.children.push(updated_node);
            }
        }
    }
}

/// Aggregates metrics for the root node
fn aggregate_root_metrics(dir_map: &mut HashMap<PathBuf, TreeNode>, root_path: &Path) {
    if let Some(root) = dir_map.get_mut(root_path) {
        let total_loc: usize = root.children.iter().map(|c| c.loc).sum();
        let max_modified = root
            .children
            .iter()
            .map(|c| c.last_modified)
            .max()
            .unwrap_or(SystemTime::now());

        root.loc = total_loc;
        root.complexity = calculate_complexity(total_loc);
        root.last_modified = max_modified;
    }
}

//! Transform module for converting flat file lists to hierarchical trees
//!
//! This module provides the core transformation logic used by both the API
//! and Tauri layers to convert flat file metrics into hierarchical tree
//! structures for visualization.

mod path_utils;
mod tree_builder;
mod metric_aggregator;

use crate::error::CodeVizError;
use crate::models::{FileMetrics, TreeNode};
use path_utils::find_common_root;
use tree_builder::{build_directory_map, build_file_nodes, attach_file_nodes_to_parents, create_empty_root};
use metric_aggregator::aggregate_directory_metrics;
use std::path::PathBuf;

/// Converts a flat list of file metrics into a hierarchical tree structure
///
/// This is the main entry point for transforming flat file data into a tree
/// hierarchy. It handles both absolute and relative paths, creates intermediate
/// directory nodes, and aggregates metrics up the tree.
///
/// # Arguments
/// * `files` - Flat vector of file metrics from code-viz-core analysis
///
/// # Returns
/// A Result containing the root TreeNode or a CodeVizError
///
/// # Errors
/// Returns `CodeVizError::TransformError` if the root node cannot be extracted
///
/// # Examples
/// ```
/// use code_viz_core::transform::flat_to_hierarchy;
/// use code_viz_core::models::FileMetrics;
/// use std::path::PathBuf;
/// use std::time::SystemTime;
///
/// let files = vec![
///     FileMetrics {
///         path: PathBuf::from("src/main.rs"),
///         language: "rust".to_string(),
///         loc: 100,
///         size_bytes: 2048,
///         function_count: 5,
///         last_modified: SystemTime::now(),
///         dead_function_count: None,
///         dead_code_loc: None,
///         dead_code_ratio: None,
///         coupling: None,
///         code_churn: None,
///         ai_bloat_index: None,
///         cognitive_complexity: None,
///         test_coverage: None,
///     },
/// ];
///
/// let tree = flat_to_hierarchy(files).unwrap();
/// assert_eq!(tree.name, "root");
/// ```
pub fn flat_to_hierarchy(files: Vec<FileMetrics>) -> Result<TreeNode, CodeVizError> {
    if files.is_empty() {
        return Ok(create_empty_root());
    }

    let has_absolute_paths = files.iter().any(|f| f.path.is_absolute());
    let (root_path, project_name) = determine_root_path(&files, has_absolute_paths);
    let root_node_path = if has_absolute_paths {
        PathBuf::from("")
    } else {
        root_path.clone()
    };

    let mut dir_map = build_directory_map(&project_name, &root_node_path);
    let file_nodes = build_file_nodes(files, has_absolute_paths, &root_path, &mut dir_map, &root_node_path);
    attach_file_nodes_to_parents(file_nodes, &mut dir_map, &root_node_path);
    aggregate_directory_metrics(&mut dir_map, &root_node_path);

    dir_map.remove(&root_node_path).ok_or_else(|| {
        CodeVizError::analysis(
            "tree_transform",
            "Root node missing from directory map after tree construction"
        )
    })
}

/// Determines the root path and project name from file list
fn determine_root_path(files: &[FileMetrics], has_absolute_paths: bool) -> (PathBuf, String) {
    if has_absolute_paths {
        let common_root = find_common_root(files);
        let proj_name = common_root
            .file_name()
            .and_then(|n| n.to_str())
            .unwrap_or("root")
            .to_string();
        (common_root, proj_name)
    } else {
        (PathBuf::from("/"), "root".to_string())
    }
}

//! Path handling utilities for tree transformation
//!
//! This module provides functions for working with file paths during the
//! transformation from flat file lists to hierarchical trees.

use crate::models::FileMetrics;
use std::path::{Path, PathBuf};

/// Finds the common root directory from a list of file paths
///
/// This function identifies the deepest common directory that contains all files.
/// Used to convert absolute filesystem paths to project-relative paths.
///
/// # Arguments
/// * `files` - Vector of file metrics with paths
///
/// # Returns
/// The common root directory path
///
/// # Examples
/// ```
/// // Files: /home/user/project/src/main.rs, /home/user/project/tests/test.rs
/// // Returns: /home/user/project
/// ```
pub fn find_common_root(files: &[FileMetrics]) -> PathBuf {
    if files.is_empty() {
        return PathBuf::from("/");
    }

    // Get the parent directories of all files
    let parents: Vec<PathBuf> = files
        .iter()
        .filter_map(|f| f.path.parent())
        .map(|p| p.to_path_buf())
        .collect();

    if parents.is_empty() {
        return PathBuf::from("/");
    }

    // Start with the first parent as the candidate
    let mut common = parents[0].clone();

    // Find the common ancestor of all parent directories
    for parent in parents.iter().skip(1) {
        // Walk up the tree until we find a common ancestor
        while !parent.starts_with(&common) && common != Path::new("/") {
            common = common
                .parent()
                .unwrap_or(Path::new("/"))
                .to_path_buf();
        }
    }

    // If all files have the same parent directory AND they're in a subdirectory
    // (not at root level), go up one more level to get the project root.
    // For example, if all files are in "src/", we want the parent of "src/" as root.
    let all_same_parent = parents.iter().all(|p| p == &common);
    if all_same_parent && parents.len() > 1 {
        // Multiple files in the same directory suggests it's a subdirectory
        common = common
            .parent()
            .unwrap_or(&common)
            .to_path_buf();
    }

    common
}

/// Strips a prefix from a path, returning a relative path
///
/// If the path doesn't start with the prefix, returns the path as-is.
///
/// # Arguments
/// * `path` - The absolute path to strip
/// * `prefix` - The prefix to remove
///
/// # Returns
/// A relative path with the prefix removed
pub fn strip_prefix(path: &Path, prefix: &Path) -> PathBuf {
    path.strip_prefix(prefix)
        .unwrap_or(path)
        .to_path_buf()
}

/// Gets the parent path of a given path, defaulting to root if no parent
///
/// # Arguments
/// * `path` - The path to get the parent of
/// * `root_path` - The root path to use as default
///
/// # Returns
/// The parent path, or root_path if no parent exists
pub fn get_parent_path(path: &Path, root_path: &Path) -> PathBuf {
    path.parent()
        .filter(|p| !p.as_os_str().is_empty())
        .map(|p| p.to_path_buf())
        .unwrap_or_else(|| root_path.to_path_buf())
}

