        );
        symbols.insert("A".to_string(), create_symbol("A", "funcA", "a.ts"));
        symbols.insert("B".to_string(), create_symbol("B", "funcB", "b.ts"));
        symbols.insert("C".to_string(), create_symbol("C", "funcC", "c.ts"));
        symbols.insert("D".to_string(), create_symbol("D", "funcD", "d.ts"));
        symbols.insert("E".to_string(), create_symbol("E", "funcE", "e.ts"));

        imports.insert("Entry1".to_string(), vec!["A".to_string()]);
        imports.insert("A".to_string(), vec!["B".to_string()]);
        imports.insert("Entry2".to_string(), vec!["C".to_string()]);
        imports.insert("C".to_string(), vec!["D".to_string()]);

        let graph = SymbolGraph {
            symbols,
            imports,
            exports,
        };

        let mut analyzer = ReachabilityAnalyzer::new(graph.clone());

        // Multiple entry points
        let entry_points = vec!["Entry1".to_string(), "Entry2".to_string()];
        let reachable = analyzer
            .analyze(entry_points)
            .expect("Analysis should succeed");

        // All except E should be reachable
        assert_eq!(reachable.len(), 6, "Should have 6 reachable symbols");
        assert!(reachable.contains("Entry1"));
        assert!(reachable.contains("Entry2"));
        assert!(reachable.contains("A"));
        assert!(reachable.contains("B"));
        assert!(reachable.contains("C"));
        assert!(reachable.contains("D"));
        assert!(!reachable.contains("E"), "E should not be reachable");

        // Verify E is identified as dead
        let dead = identify_dead_code(&graph, &reachable);
        assert_eq!(dead.len(), 1);
        assert_eq!(dead[0].id, "E");
    }

    #[test]
    fn test_no_entry_points_error() {
        let graph = create_test_graph();
        let mut analyzer = ReachabilityAnalyzer::new(graph);

        // Empty entry points should error
        let entry_points = vec![];
        let result = analyzer.analyze(entry_points);

        assert!(
            result.is_err(),
            "Should return error for empty entry points"
        );
        match result {
            Err(ReachabilityError::NoEntryPoints) => {
                // Expected error
            }
            _ => panic!("Expected NoEntryPoints error"),
        }
    }

    #[test]
    fn test_multiple_calls_to_analyze() {
        let graph = create_test_graph();
        let mut analyzer = ReachabilityAnalyzer::new(graph);

        // First analysis
        let entry_points1 = vec!["A".to_string()];
        let reachable1 = analyzer
            .analyze(entry_points1)
            .expect("First analysis should succeed");
        assert_eq!(reachable1.len(), 3);

        // Second analysis should clear previous state
        let entry_points2 = vec!["D".to_string()];
        let reachable2 = analyzer
            .analyze(entry_points2)
            .expect("Second analysis should succeed");

        // Only D should be reachable now
        assert_eq!(reachable2.len(), 1);
        assert!(reachable2.contains("D"));
    }

    #[test]
    fn test_empty_graph() {
        let graph = SymbolGraph {
            symbols: HashMap::new(),
            imports: HashMap::new(),
            exports: HashMap::new(),
        };

        let mut analyzer = ReachabilityAnalyzer::new(graph.clone());

        // Even with entry point, should handle gracefully
        let entry_points = vec!["NonExistent".to_string()];
        let reachable = analyzer
            .analyze(entry_points)
            .expect("Analysis should succeed");

        // No symbols should be reachable (entry point doesn't exist)
        assert_eq!(
            reachable.len(),
            0,
            "No symbols should be reachable in empty graph"
        );

        // No dead code either
        let dead = identify_dead_code(&graph, &reachable);
        assert_eq!(dead.len(), 0);
    }

    #[test]
    fn test_symbol_with_no_imports() {
        let mut symbols = HashMap::new();
        let imports = HashMap::new();
        let exports = HashMap::new();

        // Single symbol with no dependencies
        symbols.insert(
            "Isolated".to_string(),
            create_symbol("Isolated", "isolated", "isolated.ts"),
        );

        let graph = SymbolGraph {
            symbols,
            imports,
            exports,
        };

        let mut analyzer = ReachabilityAnalyzer::new(graph.clone());

        // If Isolated is an entry point, it should be reachable
        let entry_points = vec!["Isolated".to_string()];
        let reachable = analyzer
            .analyze(entry_points)
            .expect("Analysis should succeed");

        assert_eq!(reachable.len(), 1);
        assert!(reachable.contains("Isolated"));

        // No dead code
        let dead = identify_dead_code(&graph, &reachable);
        assert_eq!(dead.len(), 0);
    }
}

//! Symbol graph builder implementation.

use super::extractors::{extract_symbol_name, is_symbol_exported, is_test_file};
use super::queries::{get_import_query, get_symbol_query};
use super::resolver::resolve_import_path;
use super::{GraphError, SymbolGraph};
use crate::models::{Symbol, SymbolId, SymbolKind};
use ahash::AHashMap as HashMap;
use code_viz_core::parser::LanguageParser;
use rayon::prelude::*;
use std::path::{Path, PathBuf};
use std::sync::Mutex;
use tree_sitter::{Query, QueryCursor, Tree};

// Type aliases to reduce complexity
type SymbolMap = HashMap<SymbolId, Symbol>;
type ExportMap = HashMap<PathBuf, Vec<SymbolId>>;
type ImportMap = HashMap<SymbolId, Vec<SymbolId>>;
type SymbolExtractionResult = (PathBuf, Vec<Symbol>, Vec<SymbolId>);
type ImportResolutionResult = Vec<(SymbolId, Vec<SymbolId>)>;

/// Builder for constructing symbol graphs
pub struct SymbolGraphBuilder {
    graph: HashMap<SymbolId, Symbol>,
    dependencies: HashMap<SymbolId, Vec<SymbolId>>,
}

impl SymbolGraphBuilder {
    /// Create a new symbol graph builder
    pub fn new() -> Self {
        Self {
            graph: HashMap::new(),
            dependencies: HashMap::new(),
        }
    }

    fn parse_symbol_kind(capture_name: &str) -> Option<SymbolKind> {
        match capture_name {
            "function" => Some(SymbolKind::Function),
            "arrow" => Some(SymbolKind::ArrowFunction),
            "class" => Some(SymbolKind::Class),
            "method" => Some(SymbolKind::Method),
            "variable" => Some(SymbolKind::Variable),
            _ => None,
        }
    }

    fn build_symbol_from_capture(
        &self,
        node: tree_sitter::Node,
        capture_name: &str,
        source: &str,
        path: &Path,
        is_test: bool,
    ) -> Option<Symbol> {
        let kind = Self::parse_symbol_kind(capture_name)?;
        let name = extract_symbol_name(&node, source, capture_name);
        if name.is_empty() {
            return None;
        }

        let is_exported = is_symbol_exported(&node, source);
        let start_point = node.start_position();
        let end_point = node.end_position();
        let line_start = start_point.row + 1;
        let line_end = end_point.row + 1;
        let id = format!("{}:{}:{}", path.display(), line_start, name);

        Some(Symbol {
            id,
            name,
            kind,
            path: path.to_path_buf(),
            line_start,
            line_end,
            is_exported,
            is_test,
        })
    }

    fn process_query_matches(
        &self,
        query: &Query,
        tree: &Tree,
        source: &str,
        path: &Path,
        is_test: bool,
    ) -> Vec<Symbol> {
        let mut symbols = Vec::new();
        let mut cursor = QueryCursor::new();
        let matches = cursor.matches(query, tree.root_node(), source.as_bytes());

        for m in matches {
            for capture in m.captures {
                let capture_name = &query.capture_names()[capture.index as usize];
                if let Some(symbol) = self.build_symbol_from_capture(
                    capture.node,
                    capture_name,
                    source,
                    path,
                    is_test,
                ) {
                    symbols.push(symbol);
                }
            }
        }

        symbols
    }

    /// Extract symbols from a single file using Tree-sitter
    ///
    /// # Arguments
    /// * `path` - File path
    /// * `source` - Source code content
    /// * `parser` - Language parser (from code-viz-core)
    ///
    /// # Returns
    /// List of symbols found in the file
    pub fn extract_symbols(
        &mut self,
        path: &Path,
        source: &str,
        parser: &dyn LanguageParser,
    ) -> Result<Vec<Symbol>, GraphError> {
        let tree = parser.parse(source).map_err(|e| GraphError::ParseError {
            file: path.to_path_buf(),
            message: e.to_string(),
        })?;

        let is_test = is_test_file(path);
        let query = get_symbol_query(parser.language_key())?;
        let symbols = self.process_query_matches(query, &tree, source, path, is_test);

        Ok(symbols)
    }

    /// Extract import paths from a file
    ///
    /// # Arguments
    /// * `path` - File path
    /// * `source` - Source code content
    /// * `parser` - Language parser
    ///
    /// # Returns
    /// List of import source strings (e.g., "./utils", "@/components")
    pub(crate) fn extract_imports(
        &self,
        path: &Path,
        source: &str,
        parser: &dyn LanguageParser,
    ) -> Result<Vec<String>, GraphError> {
        // Parse the source code
        let tree = parser.parse(source).map_err(|e| GraphError::ParseError {
            file: path.to_path_buf(),
            message: e.to_string(),
        })?;

        let mut imports = Vec::new();

        // Get the appropriate query based on language
        let query = get_import_query(parser.language_key())?;
        let mut cursor = QueryCursor::new();

        // Execute the query on the tree
        let matches = cursor.matches(query, tree.root_node(), source.as_bytes());

        for m in matches {
            for capture in m.captures {
                let node = capture.node;
                let import_source = node.utf8_text(source.as_bytes()).unwrap_or("");
                if !import_source.is_empty() {
                    imports.push(import_source.to_string());
                }
            }
        }

        Ok(imports)
    }

    /// Build complete symbol graph from multiple files
    ///
    /// # Arguments
    /// * `files` - List of (file_path, source_code) tuples
    ///
    /// # Returns
    /// Complete symbol graph with all relationships
    pub fn build_graph(
        &mut self,
        files: Vec<(PathBuf, String)>,
    ) -> Result<SymbolGraph, GraphError> {
        let file_count = files.len();
        let estimated_symbols = file_count * 20;

        let available_files: HashMap<PathBuf, bool> =
            files.iter().map(|(path, _)| (path.clone(), true)).collect();

        let (all_symbols, exports) = Self::extract_all_symbols(&files, estimated_symbols, file_count)?;
        let imports = Self::build_dependency_edges(&files, &all_symbols, &exports, &available_files, estimated_symbols)?;

        Ok(SymbolGraph {
            symbols: all_symbols,
            imports,
            exports,
        })
    }

    /// Extract all symbols from files in parallel
    fn extract_all_symbols(
        files: &[(PathBuf, String)],
        estimated_symbols: usize,
        file_count: usize,
    ) -> Result<(SymbolMap, ExportMap), GraphError> {
        let all_symbols = Mutex::new(HashMap::with_capacity(estimated_symbols));
        let exports = Mutex::new(HashMap::with_capacity(file_count));

        let symbol_results: Vec<Result<SymbolExtractionResult, GraphError>> = files
            .par_iter()
            .map(|(file_path, source)| {
                let parser = Self::create_parser(file_path);
                let mut builder = SymbolGraphBuilder::new();
                let symbols = builder.extract_symbols(file_path, source, parser.as_ref())?;

                let file_exports = Self::collect_exports(&symbols);
                Ok((file_path.clone(), symbols, file_exports))
            })
            .collect();

        Self::aggregate_symbols(symbol_results, all_symbols, exports)
    }

    /// Build dependency edges between symbols
    fn build_dependency_edges(
        files: &[(PathBuf, String)],
        all_symbols: &SymbolMap,
        exports: &ExportMap,
        available_files: &HashMap<PathBuf, bool>,
        estimated_symbols: usize,
    ) -> Result<ImportMap, GraphError> {
        let imports = Mutex::new(HashMap::with_capacity(estimated_symbols));

        let import_results: Vec<Result<_, GraphError>> = files
            .par_iter()
            .map(|(file_path, source)| {
                let parser = Self::create_parser(file_path);
                let builder = SymbolGraphBuilder::new();
                let import_sources = builder.extract_imports(file_path, source, parser.as_ref())?;

                let file_imports = Self::resolve_file_imports(
                    file_path,
                    &import_sources,
                    all_symbols,
                    exports,
                    available_files,
                );

                Ok(file_imports)
            })
            .collect();

        Self::aggregate_imports(import_results, imports)
    }

    /// Create appropriate parser based on file extension
    fn create_parser(file_path: &Path) -> Box<dyn LanguageParser> {
        if file_path
            .extension()
            .and_then(|s| s.to_str())
            .map(|s| s == "ts" || s == "tsx")
            .unwrap_or(false)
        {
            Box::new(code_viz_core::parser::TypeScriptParser)
        } else {
            Box::new(code_viz_core::parser::JavaScriptParser)
        }
    }

    /// Collect exported symbols from a symbol list
    fn collect_exports(symbols: &[Symbol]) -> Vec<SymbolId> {
        symbols
            .iter()
            .filter(|s| s.is_exported)
            .map(|s| s.id.clone())
            .collect()
    }

    /// Aggregate symbol extraction results
    fn aggregate_symbols(
        results: Vec<Result<SymbolExtractionResult, GraphError>>,
        all_symbols: Mutex<SymbolMap>,
        exports: Mutex<ExportMap>,
    ) -> Result<(SymbolMap, ExportMap), GraphError> {
        for result in results {
            let (file_path, symbols, file_exports) = result?;

            let mut all_symbols_guard = all_symbols.lock()
                .expect("BUG: Mutex poisoned - indicates panic in parallel processing");
            for symbol in symbols {
                all_symbols_guard.insert(symbol.id.clone(), symbol);
            }

            if !file_exports.is_empty() {
                let mut exports_guard = exports.lock()
                    .expect("BUG: Mutex poisoned - indicates panic in parallel processing");
                exports_guard.insert(file_path, file_exports);
            }
        }

        Ok((
            all_symbols.into_inner().expect("BUG: Mutex poisoned"),
            exports.into_inner().expect("BUG: Mutex poisoned")
        ))
    }

    /// Resolve imports for a single file
    fn resolve_file_imports(
        file_path: &Path,
        import_sources: &[String],
        all_symbols: &SymbolMap,
        exports: &ExportMap,
        available_files: &HashMap<PathBuf, bool>,
    ) -> Vec<(SymbolId, Vec<SymbolId>)> {
        let mut file_imports = Vec::new();

        for import_source in import_sources {
            if let Some(resolved_path) =
                resolve_import_path(file_path, import_source, available_files)
            {
                if let Some(exported_symbols) = exports.get(&resolved_path) {
                    let file_symbols: Vec<SymbolId> = all_symbols
                        .values()
                        .filter(|s| s.path == *file_path)
                        .map(|s| s.id.clone())
                        .collect();

                    for symbol_id in file_symbols {
                        file_imports.push((symbol_id, exported_symbols.clone()));
                    }
                }
            }
        }

        file_imports
    }

    /// Aggregate import resolution results
    fn aggregate_imports(
        results: Vec<Result<ImportResolutionResult, GraphError>>,
        imports: Mutex<ImportMap>,
    ) -> Result<ImportMap, GraphError> {
        for result in results {
            let file_imports = result?;
            let mut imports_guard = imports.lock()
                .expect("BUG: Mutex poisoned - indicates panic in parallel processing");
            for (symbol_id, deps) in file_imports {
                imports_guard
                    .entry(symbol_id)
                    .or_default()
                    .extend(deps);
            }
        }

        Ok(imports.into_inner().expect("BUG: Mutex poisoned"))
    }
}

impl Default for SymbolGraphBuilder {
    fn default() -> Self {
        Self::new()
    }
}

//! Symbol extraction utilities for parsing Tree-sitter nodes.

use std::path::Path;

/// Extract the name from a Tree-sitter node
pub(super) fn extract_symbol_name(node: &tree_sitter::Node, source: &str, kind: &str) -> String {
    let mut cursor = node.walk();

    match kind {
        "function" => {
            // For function_declaration, look for name field
            for child in node.children(&mut cursor) {
                if child.kind() == "identifier" {
                    return child.utf8_text(source.as_bytes()).unwrap_or("").to_string();
                }
            }
        }
        "arrow" => {
            // For arrow functions in variable declarations, get the variable name
            // The node is the lexical_declaration, need to find the identifier
            for child in node.children(&mut cursor) {
                if child.kind() == "variable_declarator" {
                    let mut child_cursor = child.walk();
                    for subchild in child.children(&mut child_cursor) {
                        if subchild.kind() == "identifier" {
                            return subchild
                                .utf8_text(source.as_bytes())
                                .unwrap_or("")
                                .to_string();
                        }
                    }
                }
            }
        }
        "class" => {
            // For class_declaration, look for type_identifier or identifier
            for child in node.children(&mut cursor) {
                if child.kind() == "type_identifier" || child.kind() == "identifier" {
                    return child.utf8_text(source.as_bytes()).unwrap_or("").to_string();
                }
            }
        }
        "method" => {
            // For method_definition, look for property_identifier
            for child in node.children(&mut cursor) {
                if child.kind() == "property_identifier" {
                    return child.utf8_text(source.as_bytes()).unwrap_or("").to_string();
                }
            }
        }
        _ => {}
    }

    String::new()
}

/// Check if a symbol is exported by examining parent nodes
pub(super) fn is_symbol_exported(node: &tree_sitter::Node, source: &str) -> bool {
    let mut current = *node;

    // Walk up the tree to find export declarations
    while let Some(parent) = current.parent() {
        let kind = parent.kind();

        // Check for export declarations
        if kind == "export_statement" {
            return true;
        }

        // Check for "export default"
        if kind == "export_statement" {
            let text = parent.utf8_text(source.as_bytes()).unwrap_or("");
            if text.starts_with("export default") || text.starts_with("export {") {
                return true;
            }
        }

        current = parent;
    }

    false
}

/// Check if a file is a test file based on its path
pub(super) fn is_test_file(path: &Path) -> bool {
    let path_str = path.to_string_lossy();
    path_str.contains(".test.")
        || path_str.contains(".spec.")
        || path_str.contains("__tests__")
        || path_str.contains("/test/")
        || path_str.contains("/tests/")
        || path_str.starts_with("test/")
        || path_str.starts_with("tests/")
}

//! Symbol graph construction from source code.
//!
//! This module handles extracting symbols (functions, classes, imports, exports)
//! from source files using Tree-sitter and building a dependency graph showing
//! import/export relationships.

mod builder;
mod extractors;
mod queries;
mod resolver;

#[cfg(test)]
mod tests;

pub use builder::SymbolGraphBuilder;

use crate::models::{Symbol, SymbolId};
use ahash::AHashMap as HashMap;
use std::path::PathBuf;
use thiserror::Error;

/// Error type for symbol graph operations
#[derive(Debug, Error)]
pub enum GraphError {
    /// Failed to parse source code
    #[error("Parse error in {file}: {message}")]
    ParseError {
        /// File that failed to parse
        file: PathBuf,
        /// Error message
        message: String,
    },

    /// Failed to resolve import
    #[error("Failed to resolve import: {0}")]
    ImportResolutionError(String),

    /// I/O error
    #[error("I/O error: {0}")]
    Io(#[from] std::io::Error),
}

/// Symbol graph containing all symbols and their relationships
#[derive(Debug, Clone, serde::Serialize, serde::Deserialize)]
pub struct SymbolGraph {
    /// All symbols indexed by their ID
    pub symbols: HashMap<SymbolId, Symbol>,

    /// Import relationships: symbol -> list of symbols it imports/depends on
    pub imports: HashMap<SymbolId, Vec<SymbolId>>,

    /// Exported symbols per file: file path -> list of exported symbol IDs
    pub exports: HashMap<PathBuf, Vec<SymbolId>>,
}

//! Tree-sitter query compilation for symbol and import extraction.

use super::GraphError;
use std::path::PathBuf;
use std::sync::OnceLock;
use tree_sitter::Query;

/// Get the Tree-sitter query for extracting symbols from a specific language
pub(super) fn get_symbol_query(language: &str) -> Result<&'static Query, GraphError> {
    match language {
        "typescript" | "tsx" => {
            static TS_QUERY: OnceLock<Query> = OnceLock::new();
            Ok(TS_QUERY.get_or_init(|| {
                Query::new(
                    tree_sitter_typescript::language_typescript(),
                    r#"
                    (function_declaration) @function
                    (lexical_declaration
                        (variable_declarator
                            value: (arrow_function))) @arrow
                    (variable_declaration
                        (variable_declarator
                            value: (arrow_function))) @arrow
                    (class_declaration) @class
                    (method_definition) @method
                    "#,
                )
                // Programming error: Hardcoded query string is validated at compile-time
                // and should never fail. If this fails, it indicates a bug in the query syntax.
                .expect("Invalid TypeScript symbol query")
            }))
        }
        "javascript" | "jsx" => {
            static JS_QUERY: OnceLock<Query> = OnceLock::new();
            Ok(JS_QUERY.get_or_init(|| {
                Query::new(
                    tree_sitter_javascript::language(),
                    r#"
                    (function_declaration) @function
                    (lexical_declaration
                        (variable_declarator
                            value: (arrow_function))) @arrow
                    (variable_declaration
                        (variable_declarator
                            value: (arrow_function))) @arrow
                    (class_declaration) @class
                    (method_definition) @method
                    "#,
                )
                // Programming error: Hardcoded query string is validated at compile-time
                // and should never fail. If this fails, it indicates a bug in the query syntax.
                .expect("Invalid JavaScript symbol query")
            }))
        }
        _ => Err(GraphError::ParseError {
            file: PathBuf::new(),
            message: format!("Unsupported language for dead code analysis: {}", language),
        }),
    }
}

/// Get the Tree-sitter query for extracting imports from a specific language
pub(super) fn get_import_query(language: &str) -> Result<&'static Query, GraphError> {
    match language {
        "typescript" | "tsx" => {
            static TS_QUERY: OnceLock<Query> = OnceLock::new();
            Ok(TS_QUERY.get_or_init(|| {
                Query::new(
                    tree_sitter_typescript::language_typescript(),
                    r#"
                    (import_statement
                        source: (string) @import_source)
                    "#,
                )
                // Programming error: Hardcoded query string is validated at compile-time
                // and should never fail. If this fails, it indicates a bug in the query syntax.
                .expect("Invalid TypeScript import query")
            }))
        }
        "javascript" | "jsx" => {
            static JS_QUERY: OnceLock<Query> = OnceLock::new();
            Ok(JS_QUERY.get_or_init(|| {
                Query::new(
                    tree_sitter_javascript::language(),
                    r#"
                    (import_statement
                        source: (string) @import_source)
                    "#,
                )
                // Programming error: Hardcoded query string is validated at compile-time
                // and should never fail. If this fails, it indicates a bug in the query syntax.
                .expect("Invalid JavaScript import query")
            }))
        }
        _ => Err(GraphError::ParseError {
            file: PathBuf::new(),
            message: format!("Unsupported language for imports: {}", language),
        }),
    }
}

//! Import path resolution for symbol graph construction.

use ahash::AHashMap as HashMap;
use std::path::{Path, PathBuf};

/// Resolve an import path relative to the importing file
///
/// Handles:
/// - Relative imports: "./utils" -> "../src/utils.ts"
/// - Package imports: "@/utils" or "~/utils" (TypeScript path aliases)
/// - Extension-less imports: "./utils" could be "./utils.ts" or "./utils/index.ts"
pub(super) fn resolve_import_path(
    importer_path: &Path,
    import_source: &str,
    available_files: &HashMap<PathBuf, bool>,
) -> Option<PathBuf> {
    // Remove quotes from import source
    let import_source = import_source.trim_matches(|c| c == '"' || c == '\'');

    // Skip node_modules and package imports (e.g., "react", "lodash")
    if !import_source.starts_with('.')
        && !import_source.starts_with('/')
        && !import_source.starts_with("@/")
        && !import_source.starts_with("~/")
    {
        return None;
    }

    // Get the directory of the importing file
    let importer_dir = importer_path.parent()?;

    // Handle TypeScript path aliases (@/ and ~/ typically map to src/)
    let import_path_str = if import_source.starts_with("@/") || import_source.starts_with("~/") {
        import_source[2..].to_string()
    } else {
        import_source.to_string()
    };

    // Resolve the path relative to the importer
    let base_path = if import_path_str.starts_with("./") || import_path_str.starts_with("../") {
        importer_dir.join(&import_path_str)
    } else {
        // Assume path alias points to project root (simplified)
        PathBuf::from(&import_path_str)
    };

    // Try to resolve with common extensions
    let extensions = ["", ".ts", ".tsx", ".js", ".jsx"];
    for ext in &extensions {
        let candidate = if ext.is_empty() {
            base_path.clone()
        } else {
            base_path.with_extension(&ext[1..]) // Remove the leading dot
        };

        if available_files.contains_key(&candidate) {
            return Some(candidate);
        }
    }

    // Try index file resolution (import "./dir" -> "./dir/index.ts")
    for ext in &[".ts", ".tsx", ".js", ".jsx"] {
        let index_path = base_path.join(format!("index{}", ext));
        if available_files.contains_key(&index_path) {
            return Some(index_path);
        }
    }

    // Log warning for unresolved import but don't fail
    None
}

//! Tests for symbol graph construction.
//!
//! Note: unwrap() is acceptable in test code because test panics indicate
//! test fixture or assertion failures, which is the expected behavior.

use super::builder::SymbolGraphBuilder;
use super::extractors::is_test_file;
use super::resolver::resolve_import_path;
use ahash::AHashMap as HashMap;
use crate::models::SymbolKind;
use code_viz_core::parser::TypeScriptParser;
use std::path::{Path, PathBuf};

#[test]
fn test_extract_typescript_functions() {
    let source = r#"
        function regularFunction() {
            return 42;
        }

        const arrowFunc = () => {
            return 'hello';
        };
    "#;

    let parser = TypeScriptParser;
    let path = Path::new("test.ts");
    let mut builder = SymbolGraphBuilder::new();

    let symbols = builder.extract_symbols(path, source, &parser).unwrap();

    assert_eq!(symbols.len(), 2);
    assert!(symbols
        .iter()
        .any(|s| s.name == "regularFunction" && s.kind == SymbolKind::Function));
    assert!(symbols
        .iter()
        .any(|s| s.name == "arrowFunc" && s.kind == SymbolKind::ArrowFunction));
}

#[test]
fn test_extract_classes_and_methods() {
    let source = r#"
        class MyClass {
            myMethod() {
                return 'test';
            }
        }
    "#;

    let parser = TypeScriptParser;
    let path = Path::new("test.ts");
    let mut builder = SymbolGraphBuilder::new();

    let symbols = builder.extract_symbols(path, source, &parser).unwrap();

    assert_eq!(symbols.len(), 2);
    assert!(symbols
        .iter()
        .any(|s| s.name == "MyClass" && s.kind == SymbolKind::Class));
    assert!(symbols
        .iter()
        .any(|s| s.name == "myMethod" && s.kind == SymbolKind::Method));
}

#[test]
fn test_exported_symbols() {
    let source = r#"
        export function exportedFunc() {
            return 1;
        }

        function privateFunc() {
            return 2;
        }

        export default class ExportedClass {
        }
    "#;

    let parser = TypeScriptParser;
    let path = Path::new("test.ts");
    let mut builder = SymbolGraphBuilder::new();

    let symbols = builder.extract_symbols(path, source, &parser).unwrap();

    let exported_func = symbols.iter().find(|s| s.name == "exportedFunc").unwrap();
    assert!(exported_func.is_exported);

    let private_func = symbols.iter().find(|s| s.name == "privateFunc").unwrap();
    assert!(!private_func.is_exported);

    let exported_class = symbols.iter().find(|s| s.name == "ExportedClass").unwrap();
    assert!(exported_class.is_exported);
}

