    let files = vec![
        (
            PathBuf::from("a.ts"),
            r#"
            export function funcA() {}
            "#
            .to_string(),
        ),
        (
            PathBuf::from("b.ts"),
            r#"
            import { funcA } from "./a";
            export function funcB() {
                funcA();
            }
            "#
            .to_string(),
        ),
        (
            PathBuf::from("c.ts"),
            r#"
            import { funcB } from "./b";
            function funcC() {
                funcB();
            }
            "#
            .to_string(),
        ),
    ];

    let graph = builder.build_graph(files).unwrap();

