#[async_trait]
impl AppContext for TauriContext {
    async fn emit_event(&self, event: &str, payload: Value) -> Result<()> {
        self.app.emit(event, payload)?;
        Ok(())
    }

    fn get_app_dir(&self) -> PathBuf {
        self.app
            .path()
            .app_data_dir()
            .unwrap_or_else(|_| std::env::current_dir().unwrap_or_default())
    }

