//! Code-viz Web Server Library
//!
//! Provides HTTP/REST API access to code-viz functionality.

pub mod context;
pub mod routes;

pub use context::{WebContext, RealFileSystem, RealGit};

//! Code-viz Web Server
//!
//! HTTP/REST API server that provides the same functionality as the Tauri desktop app.
//! Uses the shared code-viz-api layer (SSOT) to ensure zero duplication with Tauri.
//!
//! Architecture:
//! ```text
//! HTTP Request → Axum Route → code-viz-api handler → Response
//!                                  ↑
//!                           (Same handler as Tauri)
//! ```

mod context;
mod routes;

use axum::{
    routing::{get, post},
    Router,
};
use std::net::SocketAddr;
use tower_http::{
    cors::{Any, CorsLayer},
    services::ServeDir,
    trace::TraceLayer,
};
use tracing_subscriber::{layer::SubscriberExt, util::SubscriberInitExt};

#[tokio::main]
async fn main() -> anyhow::Result<()> {
    // Initialize tracing
    tracing_subscriber::registry()
        .with(
            tracing_subscriber::EnvFilter::try_from_default_env()
                .unwrap_or_else(|_| "code_viz_web=debug,tower_http=debug".into()),
        )
        .with(tracing_subscriber::fmt::layer())
        .init();

    // Build API routes
    let api_routes = Router::new()
        .route("/analyze", post(routes::post_analyze))
        .route("/dead-code", post(routes::post_dead_code))
        .route("/health", get(routes::health_check));

    // Serve frontend static files from dist/
    let frontend_service = ServeDir::new("dist")
        .not_found_service(ServeDir::new("dist/index.html"));

    // Build complete app
    let app = Router::new()
        .nest("/api", api_routes)
        .fallback_service(frontend_service)
        .layer(
            CorsLayer::new()
                .allow_origin(Any)
                .allow_methods(Any)
                .allow_headers(Any),
        )
        .layer(TraceLayer::new_for_http());

    // Start server - bind to 0.0.0.0 to allow external access
    let addr = SocketAddr::from(([0, 0, 0, 0], 8080));
    tracing::info!("🚀 Code-viz web server starting on http://{}", addr);
    tracing::info!("   Accessible from other machines at http://<your-ip>:3000");
    tracing::info!("   API endpoints:");
    tracing::info!("   - POST http://{}/api/analyze", addr);
    tracing::info!("   - POST http://{}/api/dead-code", addr);
    tracing::info!("   - GET  http://{}/api/health", addr);
    tracing::info!("   Frontend: http://{}", addr);

    let listener = tokio::net::TcpListener::bind(addr).await?;
    axum::serve(listener, app).await?;

    Ok(())
}

//! Web API routes - HTTP wrappers around shared SSOT handlers
//!
//! These routes are thin wrappers around code-viz-api handlers,
//! identical in function to the Tauri commands but using HTTP transport.

use axum::{
    extract::Json,
    http::StatusCode,
    response::{IntoResponse, Response},
};
use code_viz_api::{analyze_repository_handler, analyze_dead_code_handler, TreeNode, AnalysisOptions};
use code_viz_dead_code::DeadCodeResult;
use serde::{Deserialize, Serialize};

use crate::context::{WebContext, RealFileSystem, RealGit};

/// Request body for repository analysis
#[derive(Debug, Serialize, Deserialize)]
#[serde(rename_all = "camelCase")]
pub struct AnalyzeRequest {
    pub path: String,
    #[serde(default)]
    pub options: AnalysisOptions,
    #[serde(skip_serializing_if = "Option::is_none")]
    pub request_id: Option<String>,
}

/// Request body for dead code analysis
#[derive(Debug, Serialize, Deserialize)]
#[serde(rename_all = "camelCase")]
pub struct DeadCodeRequest {
    pub path: String,
    pub min_confidence: u8,
    #[serde(skip_serializing_if = "Option::is_none")]
    pub request_id: Option<String>,
}

/// API error response
#[derive(Debug, Serialize)]
pub struct ErrorResponse {
    pub error: String,
}

/// Web-specific error wrapper (needed to avoid orphan rule)
pub struct WebError(code_viz_api::ApiError);

impl From<code_viz_api::ApiError> for WebError {
    fn from(err: code_viz_api::ApiError) -> Self {
        WebError(err)
    }
}

/// Convert WebError to HTTP response
impl IntoResponse for WebError {
    fn into_response(self) -> Response {
        let (status, error_message) = match &self.0 {
            code_viz_api::ApiError::InvalidPath(_) => (StatusCode::BAD_REQUEST, self.0.to_user_message()),
            code_viz_api::ApiError::AnalysisFailed(_) => (StatusCode::INTERNAL_SERVER_ERROR, self.0.to_user_message()),
            code_viz_api::ApiError::DeadCodeFailed(_) => (StatusCode::INTERNAL_SERVER_ERROR, self.0.to_user_message()),
            code_viz_api::ApiError::TransformError(_) => (StatusCode::INTERNAL_SERVER_ERROR, self.0.to_user_message()),
            code_viz_api::ApiError::Io(_) => (StatusCode::INTERNAL_SERVER_ERROR, self.0.to_user_message()),
            code_viz_api::ApiError::Internal(_) => (StatusCode::INTERNAL_SERVER_ERROR, self.0.to_user_message()),
        };

        let body = Json(ErrorResponse {
            error: error_message,
        });

        (status, body).into_response()
    }
}

/// POST /api/analyze - Analyze a repository
///
/// This route is the HTTP equivalent of the Tauri `analyze_repository` command.
/// It uses the EXACT SAME handler from code-viz-api (SSOT).
pub async fn post_analyze(
    Json(req): Json<AnalyzeRequest>,
) -> Result<Json<TreeNode>, WebError> {
    tracing::info!(path = %req.path, request_id = ?req.request_id, options = ?req.options, "POST /api/analyze");

    let ctx = WebContext::new();
    let fs = RealFileSystem::new();

    // Call the shared SSOT handler (same as Tauri uses)
    let git = code_viz_core::context::RealGit::new();
    let tree = analyze_repository_handler(ctx, fs, git, req.path, req.options, req.request_id).await?;

    Ok(Json(tree))
}

/// POST /api/dead-code - Analyze dead code
///
/// This route is the HTTP equivalent of the Tauri `analyze_dead_code_command` command.
/// It uses the EXACT SAME handler from code-viz-api (SSOT).
pub async fn post_dead_code(
    Json(req): Json<DeadCodeRequest>,
) -> Result<Json<DeadCodeResult>, WebError> {
    tracing::info!(
        path = %req.path,
        min_confidence = %req.min_confidence,
        request_id = ?req.request_id,
        "POST /api/dead-code"
    );

    let ctx = WebContext::new();
    let fs = RealFileSystem::new();
    let git = RealGit::new();

    // Call the shared SSOT handler (same as Tauri uses)
    let result = analyze_dead_code_handler(ctx, fs, git, req.path, req.min_confidence, req.request_id).await?;

    Ok(Json(result))
}

/// GET /health - Health check endpoint
pub async fn health_check() -> impl IntoResponse {
    Json(serde_json::json!({
        "status": "healthy",
        "service": "code-viz-web"
    }))
}

